    $dir = $siteDir . '/static-' . $suffix;
    mkdir($dir . '/core', 0700, true);
    $modx = fakeSite($dir);
    $context = new Context($modx, $dev->token, $dev->corePath, function () {});
    $context->sessionId = 'static-session-0001';
    return array($modx, $context, $dir);
};
