    check('settings: context with resources is refused, nothing lost', $e && $e->errorCode === 'validation_failed' && strpos($e->getMessage(), '1 resource') !== false
        && $setSite->row('modContext', 'shop') !== null && $setSite->row('modResource', 501) !== null);
}
