$e = throws('user: password_min_length', ApiException::class, function () use ($call, $uAdmin, $secretPw) { $call($uAdmin, 'create', array('kind' => 'user', 'fields' => array('username' => 'длинный', 'password' => $secretPw, 'email' => 'long@example.com'))); });
