$changedPassword = $call($uAdmin, 'update', array('kind' => 'user', 'id' => $ivanId, 'fields' => array('password' => $secretPw2)));
check('user: password change', $changedPassword['changed'] === array('password') && $userRow($ivanId)['password'] !== $hashBefore
