    && $call($aAdmin, 'get', array('kind' => 'policy_template', 'id' => $tplCopy['id']))['relations']['permissions'] === array());
$call($aAdmin, 'undo', array('changeset_id' => $tplCopy['changeset_id'], 'confirm' => true));
