    && $aSite->getCount('modAccessPolicy', array('template' => $tplId)) === 0 && count($tplDelDiff['objects']) === 3 && $aFlushes() > $flushBase
    && array_count_values(array_column($tplDelDiff['objects'], 'kind')) == array('policy_template' => 1, 'access_policy' => 2));
$flushBase = $aFlushes();
