    && $call($aAdmin, 'delete', array('kind' => 'policy_template', 'id' => $builtinTplCopy['id']))['deleted'] === true);
foreach (array('policy 30 (resource group rule)' => 40, 'policy 31 (context rule)' => 41) as $label => $usedTpl) {
