    foreach (array('msProductData', 'msProductOption', 'msCategoryMember', 'msCategoryOption', 'msOption') as $class) {
        $rows = array();
        foreach ($sSite->tableDump($class) as $row) { ksort($row); $rows[] = json_encode($row, JSON_UNESCAPED_UNICODE); }
        sort($rows);
        $out[$class] = $rows;
