}
$e = throws('ms2: ms2_categories must be a list', ApiException::class, function () use ($call, $sEditor, $phoneId) { $call($sEditor, 'update', array('kind' => 'resource', 'id' => $phoneId, 'relations' => array('ms2_categories' => array('a' => 1)))); });
