    && $sSite->getCount('msCategoryMember', array('product_id' => $phoneCopy['id'])) === 0);
$docCopy = $call($sEditor, 'duplicate', array('kind' => 'resource', 'id' => $docId, 'new_name' => 'Копия статьи'));
