}
$e = throws('migx tv: item path in the message', ApiException::class, function () use ($call, $mDev, $mPage) { $call($mDev, 'update', array('kind' => 'resource', 'id' => $mPage['id'], 'relations' => array('tvs' => array('gallery' => array(array('a' => 1), 7))))); });
