$vEvTmp = $call($vDev, 'create', array('kind' => 'vp_event', 'fields' => array('name' => 'OnTmpEvent')));
$vEvSpacer = $call($vDev, 'create', array('kind' => 'vp_event', 'fields' => array('name' => 'OnSpacer')));
