check('vp_handler: undo restores the handler and its routes exactly, and clears the cache', $vSite->tableDump('vpRoute') == $vRoutesBefore && $vSite->tableDump('vpHandler') == $vHandlersBefore && $vClears() > $vClearsBefore);
$vDelE = $call($vDev, 'delete', array('kind' => 'vp_event', 'id' => $vEv1['id']));
check('vp_event: deleting an event removes all its routes', $vSite->row('vpEvent', $vEv1['id']) === null && count($vSite->tableDump('vpRoute')) === 0 && count($vSite->tableDump('vpHandler')) === count($vHandlersBefore));
$call($vDev, 'undo', array('changeset_id' => $vDelE['changeset_id'], 'confirm' => true));
check('vp_event: undo restores the event and its routes exactly', $vSite->tableDump('vpRoute') == $vRoutesBefore && $vSite->tableDump('vpEvent') == $vEventsBefore);
$vDelR = $call($vDev, 'delete', array('kind' => 'vp_route', 'id' => $vR3['id']));
$call($vDev, 'undo', array('changeset_id' => $vDelR['changeset_id'], 'confirm' => true));
check('vp_route: delete and undo restore the row exactly', $vSite->tableDump('vpRoute') == $vRoutesBefore);
$vDelR2 = $call($vDev, 'delete', array('kind' => 'vp_route', 'id' => $vR2['id']));
$vTaken = $call($vDev, 'create', array('kind' => 'vp_route', 'fields' => array('route' => '/catalog/special', 'handler' => $vH2['id'], 'event' => $vEv1['id'])));
$e = throws('vp_route: undo onto a route another one took', ApiException::class, function () use ($call, $vDev, $vDelR2) { $call($vDev, 'undo', array('changeset_id' => $vDelR2['changeset_id'], 'confirm' => true)); });
check('vp_route: such an undo is not_reversible', $e && $e->errorCode === 'not_reversible' && strpos($e->getMessage(), 'already answers') !== false);
$call($vDev, 'delete', array('kind' => 'vp_route', 'id' => $vTaken['id']));
$call($vDev, 'undo', array('changeset_id' => $vDelR2['changeset_id'], 'confirm' => true));
check('vp_route: after the route is out of the way the undo restores it', $vSite->row('vpRoute', $vR2['id'])['route'] === '/catalog/special');
// the event the routes of the earlier tests belong to is only changed by what the tests did
$vActive = $vSite->tableDump('vpRoute');
foreach ($vActive as $key => $row) { if (!in_array((int) $row['id'], array($vR1['id'], $vR2['id'], $vR3['id'], $vR4['id'], $vR5['id']), true)) { unset($vActive[$key]); } }

// ---- resolve ----
$vResolve = function ($path, $method = null, $ctx = null) use ($call, $vRead) {
    return $call($ctx ?: $vRead, 'invoke', array('kind' => 'vp_route', 'op' => 'resolve', 'args' => array('path' => $path) + ($method === null ? array() : array('method' => $method))));
};
$vSite->options['virtualpage_active'] = 1;
$vIds = function ($result) { return array_column($result['matches'], 'id'); };
$vM = $vResolve('/catalog/5');
check('resolve: a parameter route with a regex gives the value and the handler; the variable routes keep their order and the first answers',
    $vIds($vM) === array($vR1['id'], $vR3['id']) && $vM['matches'][0]['parameters'] === array('id' => '5') && $vM['matches'][0]['handler']['name'] === 'Карточка товара' && $vM['matches'][0]['handler']['type'] === 'chunk'
    && $vM['matches'][0]['handler']['entry'] === 3 && $vM['matches'][0]['event']['name'] === 'OnPageNotFound' && $vM['matches'][0]['answers'] === true && $vM['matches'][1]['answers'] === false
    && $vM['answered_by'] === $vR1['id'] && $vM['path'] === '/catalog/5' && $vM['method'] === 'GET' && $vM['matches'][0]['properties'] == (object) array('layout' => 'карточка', 'depth' => 2) && $vM['notes'] === array('An OnPageNotFound route is tried only when no resource answers the path.'));
$vM = $vResolve('/catalog/special');
check('resolve: a static route comes before the variable one that also matches', $vIds($vM) === array($vR2['id'], $vR3['id']) && $vM['matches'][0]['parameters'] == new stdClass() && $vM['matches'][1]['parameters'] === array('slug' => 'special')
    && $vM['matches'][0]['handler']['type'] === 'dynamic_resource');
$vM = $vResolve('catalog/сумка');
check('resolve: a leading slash is added as VirtualPage does, and a Cyrillic value is captured', $vIds($vM) === array($vR3['id']) && $vM['path'] === '/catalog/сумка' && $vM['matches'][0]['parameters'] === array('slug' => 'сумка'));
$vM = $vResolve('/заказ', 'POST');
check('resolve: a Cyrillic static route and its methods', $vIds($vM) === array($vR4['id']) && $vM['method'] === 'POST' && $vIds($vResolve('/заказ', 'get')) === array($vR4['id']));
check('resolve: a method mismatch matches nothing', $vResolve('/заказ', 'PUT')['matches'] === array() && $vResolve('/catalog/5', 'POST')['matches'] === array());
check('resolve: HEAD falls back to GET as the router does', $vIds($vResolve('/catalog/5', 'HEAD')) === array($vR1['id'], $vR3['id']) && $vIds($vResolve('/заказ', 'DELETE')) === array($vR5['id']));
$vOffR5 = $call($vDev, 'update', array('kind' => 'vp_route', 'id' => $vR5['id'], 'fields' => array('active' => false)));
check('resolve: an inactive route is ignored', $vResolve('/заказ', 'DELETE')['matches'] === array());
$call($vDev, 'undo', array('changeset_id' => $vOffR5['changeset_id'], 'confirm' => true));
$vOff = $call($vDev, 'update', array('kind' => 'vp_route', 'id' => $vR4['id'], 'fields' => array('active' => false)));
check('resolve: after the route is switched off it no longer answers', $vResolve('/заказ', 'POST')['matches'] === array());
$call($vDev, 'undo', array('changeset_id' => $vOff['changeset_id'], 'confirm' => true));
$vOffHandler = $call($vDev, 'update', array('kind' => 'vp_handler', 'id' => $vH3['id'], 'fields' => array('active' => false)));
check('resolve: a route of an inactive handler is ignored', $vIds($vResolve('/catalog/5')) === array($vR1['id']));
$call($vDev, 'undo', array('changeset_id' => $vOffHandler['changeset_id'], 'confirm' => true));
$vOffEvent = $call($vDev, 'update', array('kind' => 'vp_event', 'id' => $vEv1['id'], 'fields' => array('active' => false)));
check('resolve: the routes of an inactive event are ignored', $vResolve('/catalog/5')['matches'] === array());
$call($vDev, 'undo', array('changeset_id' => $vOffEvent['changeset_id'], 'confirm' => true));
$vM = $vResolve('/ничего/нет');
check('resolve: no match is {matches: []}, not an error', $vM['matches'] === array() && $vM['answered_by'] === null && $vM['path'] === '/ничего/нет' && json_encode(array('matches' => $vM['matches'])) === '{"matches":[]}');
$vOpt = $call($vDev, 'create', array('kind' => 'vp_route', 'fields' => array('route' => '/блог[/{page:\d+}[/{sort}]]', 'handler' => $vH3['id'], 'event' => $vEv2['id'])));
check('resolve: optional segments give the parameters that are present', $vResolve('/блог')['matches'][0]['parameters'] == new stdClass() && $vResolve('/блог/2')['matches'][0]['parameters'] === array('page' => '2')
    && $vResolve('/блог/2/новые')['matches'][0]['parameters'] === array('page' => '2', 'sort' => 'новые') && $vResolve('/блог/x')['matches'] === array());
$vTwo = $call($vDev, 'create', array('kind' => 'vp_route', 'fields' => array('route' => '/catalog/{any}', 'handler' => $vH4['id'], 'event' => $vEv2['id'])));
$vM = $vResolve('/catalog/5');
check('resolve: routes of the handle-request event come before those of the page-not-found event', $vIds($vM) === array($vTwo['id'], $vR1['id'], $vR3['id']) && $vM['answered_by'] === $vTwo['id']
    && strpos(implode(' ', $vM['notes']), 'An OnPageNotFound route is tried only') !== false);
check('resolve: a trailing slash does not match (no tolerance in the router)', $vResolve('/catalog/5/')['matches'] === array() || $vIds($vResolve('/catalog/5/')) === array());
$vSite->options['virtualpage_active'] = 0;
check('resolve: a note when VirtualPage is switched off', strpos(implode(' ', $vResolve('/catalog/5')['notes']), 'virtualpage_active is off') !== false);
$vSite->options['virtualpage_active'] = 1;
$e = throws('resolve: a path with a query string', ApiException::class, function () use ($vResolve) { $vResolve('/catalog/5?x=1'); });
check('resolve: a query string is refused', $e && $e->errorCode === 'validation_failed');
$e = throws('resolve: no path', ApiException::class, function () use ($call, $vRead) { $call($vRead, 'invoke', array('kind' => 'vp_route', 'op' => 'resolve', 'args' => new stdClass())); });
check('resolve: the path is required', $e && $e->errorCode === 'validation_failed');
$e = throws('resolve: with an id', ApiException::class, function () use ($call, $vRead, $vR1) { $call($vRead, 'invoke', array('kind' => 'vp_route', 'op' => 'resolve', 'id' => $vR1['id'], 'args' => array('path' => '/x'))); });
check('resolve: takes no id', $e && $e->errorCode === 'validation_failed');
$vJournalBefore = count($call($vDev, 'history', array('limit' => 100))['changesets']);
$vResolve('/catalog/5');
check('resolve: is read only and writes nothing to the journal', count($call($vDev, 'history', array('limit' => 100))['changesets']) === $vJournalBefore);
$vCatalogDelete = $call($vDev, 'delete', array('kind' => 'vp_route', 'id' => $vOpt['id']));
$call($vDev, 'delete', array('kind' => 'vp_route', 'id' => $vTwo['id']));

// ---- scopes, groups, the cache after every kind of write ----
$e = throws('vp: a read token cannot create', ApiException::class, function () use ($call, $vRead) { $call($vRead, 'create', array('kind' => 'vp_event', 'fields' => array('name' => 'OnX'))); });
check('vp: writing needs the develop scope', $e && $e->errorCode === 'forbidden_scope');
foreach (array('vp_event' => 1, 'vp_handler' => $vH2['id'], 'vp_route' => $vR2['id']) as $vKind => $vId) {
    foreach (array('update' => array('fields' => array('description' => 'x')), 'delete' => array(), 'duplicate' => array()) as $vTool => $vArgs) {
        $e = throws("vp: a content token cannot {$vTool} {$vKind}", ApiException::class, function () use ($call, $vActor, $vTool, $vKind, $vId, $vArgs) { $call($vActor('content'), $vTool, array('kind' => $vKind, 'id' => $vId) + $vArgs); });
        check("vp: {$vTool} of {$vKind} needs the develop scope", $e && $e->errorCode === 'forbidden_scope');
    }
}
check('vp: a read token reads all three kinds', $call($vRead, 'get', array('kind' => 'vp_event', 'id' => 1))['fields']['name'] === 'OnPageNotFound' && $call($vRead, 'get', array('kind' => 'vp_handler', 'id' => $vH2['id']))['fields']['name'] === 'Динамическая страница'
    && $call($vRead, 'get', array('kind' => 'vp_route', 'id' => $vR2['id']))['fields']['route'] === '/catalog/special' && $vResolve('/catalog/special', null, $vRead)['matches'] !== array());
$e = throws('vp: a token denied the group', ApiException::class, function () use ($call, $vActor) { $call($vActor('admin', array('denied_groups' => array('virtualpage'))), 'get', array('kind' => 'vp_route', 'id' => 1)); });
check('vp: a token denied the virtualpage group cannot use the kinds', $e && $e->errorCode === 'unavailable' && $e->details['reason'] === 'denied_for_token');
$e = throws('vp: denied token cannot resolve', ApiException::class, function () use ($vResolve, $vActor) { $vResolve('/catalog/5', null, $vActor('admin', array('denied_groups' => array('virtualpage')))); });
check('vp: nor run resolve', $e && $e->errorCode === 'unavailable');
$vSite->options['modxmcp.disabled_groups'] = 'virtualpage';
$e = throws('vp: group switched off', ApiException::class, function () use ($call, $vAdmin) { $call($vAdmin, 'list', array('kind' => 'vp_event')); });
check('vp: the virtualpage group switched off for the site makes the kinds unavailable', $e && $e->errorCode === 'unavailable' && $e->details['reason'] === 'disabled_group'
    && !array_intersect(array('vp_event', 'vp_handler', 'vp_route'), array_column($call($vAdmin, 'describe')['kinds'], 'kind')));
$vSite->options['modxmcp.disabled_groups'] = '';
unlink($vpCore . 'model/virtualpage/virtualpage.class.php');
$e = throws('vp: code missing', ApiException::class, function () use ($call, $vActor) { $call($vActor('admin'), 'list', array('kind' => 'vp_handler')); });
check('vp: installed but its code is gone is unavailable', $e && $e->errorCode === 'unavailable' && $e->details['reason'] === 'code_missing');
touch($vpCore . 'model/virtualpage/virtualpage.class.php');
$vC0 = $vClears();
$call($vDev, 'create', array('kind' => 'vp_event', 'fields' => array('name' => 'OnCacheProbe')));
$vC1 = $vClears();
$vProbe = $call($vDev, 'create', array('kind' => 'vp_handler', 'fields' => array('name' => 'Кэш')));
$vC2 = $vClears();
$vProbeRoute = $call($vDev, 'create', array('kind' => 'vp_route', 'fields' => array('route' => '/кэш', 'handler' => $vProbe['id'], 'event' => $vEv2['id'])));
$vC3 = $vClears();
$call($vDev, 'delete', array('kind' => 'vp_route', 'id' => $vProbeRoute['id']));
$vC4 = $vClears();
check('vp: VirtualPage\'s cache is cleared after a create of each kind and after a delete', $vC1 === $vC0 + 1 && $vC2 === $vC1 + 1 && $vC3 === $vC2 + 1 && $vC4 === $vC3 + 1);

// ---- the help topic ----
$vHelp = $call($vRead, 'help', array('topic' => 'virtualpage'));
check('vp help: the topic is served and listed, with the end-to-end example', in_array('virtualpage', $vHelp['topics'], true) && strpos($vHelp['content'], 'modx_create {kind: "vp_route"') !== false
    && strpos($vHelp['content'], '"resolve"') !== false && strpos($vHelp['content'], 'modx_check_page {url_path: "/catalog/5"}') !== false);
check('vp help: no 1.x tool name', strpos($vHelp['content'], 'modx_virtualpage_') === false && strpos($vHelp['content'], 'modx_create_element') === false);
check('vp help: the index lists the topic', strpos($call($vRead, 'help')['content'], '`virtualpage`') !== false);

// Review addition: VirtualPage 1.x wires its plugin `vpEvent` to the events routes use.
list($vp1Site, $vp1Dev) = $retentionSite();
$vp1Site->store('modNamespace', array('name' => 'virtualpage', 'path' => '{core_path}components/virtualpage/', 'assets_path' => ''));
$vp1Site->store('modPlugin', array('id' => 50, 'name' => 'vpEvent', 'plugincode' => '', 'description' => '', 'category' => 0, 'disabled' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'property_preprocess' => 0));
foreach (array('OnPageNotFound', 'OnHandleRequest') as $vpName) { $vp1Site->store('modEvent', array('name' => $vpName)); }
$vp1Site->store('modChunk', array('id' => 7, 'name' => 'страница', 'snippet' => 'x', 'description' => '', 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0));
$vp1Core = $vp1Site->getOption('core_path') . 'components/virtualpage/';
@mkdir($vp1Core . 'model/virtualpage', 0700, true);
touch($vp1Core . 'model/virtualpage/virtualpage.class.php');
touch($vp1Core . 'model/virtualpage/vproute.class.php');
$vp1Ok = true;
try { ModxMCP\Integration\VirtualPage::load($vp1Site); } catch (Throwable $e) { $vp1Ok = false; }
if ($vp1Ok && in_array('vp_route', $call($vp1Dev, 'capabilities')['kinds'], true)) {
    $vp1Event = $call($vp1Dev, 'create', array('kind' => 'vp_event', 'fields' => array('name' => 'OnPageNotFound')));
    $vp1Handler = $call($vp1Dev, 'create', array('kind' => 'vp_handler', 'fields' => array('name' => 'Каталог', 'type' => 'chunk', 'entry' => 7)));
    $vp1PluginRows = function () use ($vp1Site) { return $vp1Site->getCount('modPluginEvent', array('pluginid' => 50, 'event' => 'OnPageNotFound')); };
    check('vp 1.x: an event without routes does not wire the plugin', $vp1PluginRows() === 0);
    $vp1Route = $call($vp1Dev, 'create', array('kind' => 'vp_route', 'fields' => array('route' => '/catalog/{id:\d+}', 'handler' => $vp1Handler['id'], 'event' => $vp1Event['id'])));
    check('vp 1.x: the first route wires the plugin to its event, journaled in the same changeset', $vp1PluginRows() === 1
        && in_array('plugin', array_column($call($vp1Dev, 'history_diff', array('changeset_id' => $vp1Route['changeset_id']))['objects'], 'kind'), true));
    $call($vp1Dev, 'undo', array('changeset_id' => $vp1Route['changeset_id'], 'confirm' => true));
    check('vp 1.x: undo of the route unwires the plugin', $vp1PluginRows() === 0);
    $vp1Route = $call($vp1Dev, 'create', array('kind' => 'vp_route', 'fields' => array('route' => '/catalog/{id:\d+}', 'handler' => $vp1Handler['id'], 'event' => $vp1Event['id'])));
    $call($vp1Dev, 'delete', array('kind' => 'vp_route', 'id' => $vp1Route['id']));
    check('vp 1.x: deleting the last route of an event unwires the plugin', $vp1PluginRows() === 0);
} else {
    check('vp 1.x: VirtualPage fixture is available for the plugin tests', false);
}

// --- Manager history page: HistoryService ---
use ModxMCP\Manager\HistoryService;
$hCore = dirname(dirname(__DIR__)) . '/core/components/modxmcp/';
$hDir = realpath(sys_get_temp_dir()) . '/modxmcp-hist-' . bin2hex(random_bytes(6));
mkdir($hDir . '/core', 0700, true);
$hSite = fakeSite($hDir);
$hSite->options['modxmcp.auto_static'] = false;
$hSite->store('modUser', array('id' => 1, 'username' => 'admin', 'primary_group' => 0));
$hSite->store('modUser', array('id' => 2, 'username' => 'Иванов', 'primary_group' => 0));
$hSite->user = $hSite->getObject('modUser', 2);
$hTokens = new TokenStore($hSite);
$hTokenA = $hTokens->create('Claude Code', 'develop');
$hTokenB = $hTokens->create('Старый токен', 'develop');
$hActor = function (array $token) use ($hSite, $hCore) {
    unset($token['token']);
    $c = new Context($hSite, $token, $hCore, function () { throw new RuntimeException('no store in tests'); });
    $c->sessionId = 'session-history-0001';
    return $c;
};
$hDev = $hActor($hTokenA);
$hDevB = $hActor($hTokenB);
$hAdmin = $hActor(array('scope' => 'admin') + $hTokenA);
$hService = new HistoryService($hSite, $hSite->user);

$hCheckpoint = $call($hDev, 'checkpoint', array('label' => 'Перед работой'));
$hHead = $call($hDev, 'create', array('kind' => 'chunk', 'fields' => array('name' => 'шапка', 'content' => "<h1>\nЗаголовок\n</h1>")));       // 1
$hHeadEdit = $call($hDev, 'update', array('kind' => 'chunk', 'id' => $hHead['id'], 'fields' => array('description' => 'первая правка')));        // 2
$hFoot = $call($hDev, 'create', array('kind' => 'chunk', 'fields' => array('name' => 'подвал')));                                               // 3
$hSide = $call($hDevB, 'create', array('kind' => 'chunk', 'fields' => array('name' => 'sidebar')));                                              // 4
$hTokens->revoke($hTokenB['id']);
$hSite->store('modChunk', array('description' => 'правка в админке') + $hSite->row('modChunk', $hFoot['id']));                                  // found as 5
$call($hDev, 'update', array('kind' => 'chunk', 'id' => $hFoot['id'], 'fields' => array('description' => 'после правки в админке')));            // 6
$hGone = $hDev->journal()->commit(array('source' => 'mcp', 'token_id' => 999, 'session_id' => null, 'request_id' => null, 'tool' => 'install', 'summary' => 'запись о пакете'), array());   // 7
$hRows = $hService->changesets(array(), 100);
check('history page: every changeset listed newest first with a total', array_column($hRows['changesets'], 'changeset_id') === array(7, 6, 5, 4, 3, 2, 1) && $hRows['total'] === 7);

// authors
$hAuthor = array_column($hRows['changesets'], 'author', 'changeset_id');
check('history page: author of an MCP token is its label', $hAuthor[1] === 'Claude Code' && $hAuthor[6] === 'Claude Code');
check('history page: a revoked token keeps its label, a vanished one is named so', $hAuthor[4] === 'Старый токен' && $hAuthor[7] === '(revoked token)');
check('history page: a change found outside the journal has an unknown author', $hAuthor[5] === 'unknown' && $hRows['changesets'][2]['source'] === 'external');

// the entries are those of modx_history, plus the author (the API tool shows it too)
$hApi = $call($hDev, 'history', array('limit' => 100))['changesets'];
$hDrop = function (array $entries) { foreach ($entries as $i => $entry) { unset($entries[$i]['this_session']); } return $entries; };
check('history page: entries are the entries of modx_history', $hDrop($hRows['changesets']) === $hDrop($hApi) && $hApi[0]['author'] === '(revoked token)' && $hApi[6]['author'] === 'Claude Code');

// filters
$ids = function (array $filter, $limit = 100, $start = 0) use ($hService) { return array_column($hService->changesets($filter, $limit, $start)['changesets'], 'changeset_id'); };
check('history page: filter source', $ids(array('source' => 'mcp')) === array(7, 6, 4, 3, 2, 1) && $ids(array('source' => 'external')) === array(5) && $ids(array('source' => 'manager')) === array());
check('history page: filter kind', $ids(array('kind' => 'chunk')) === array(6, 5, 4, 3, 2, 1) && $ids(array('kind' => 'snippet')) === array());
check('history page: filter object id and key', $ids(array('kind' => 'chunk', 'id' => $hHead['id'])) === array(2, 1) && $ids(array('id' => (string) $hFoot['id'])) === array(6, 5, 3)
    && $ids(array('key' => (string) $hHead['id'])) === array(2, 1) && $ids(array('kind' => 'tv', 'id' => $hHead['id'])) === array());
check('history page: filter tool and status', $ids(array('tool' => 'update')) === array(6, 2) && $ids(array('tool' => 'install')) === array(7) && $ids(array('status' => 'undone')) === array() && count($ids(array('status' => 'committed'))) === 7);
$hSite->pdo->exec('UPDATE modx_modxmcp_changesets SET created_at = 1000000 WHERE id = 1');
check('history page: filter since and until', $ids(array('until' => 2000000)) === array(1) && $ids(array('since' => 2000000)) === array(7, 6, 5, 4, 3, 2) && $ids(array('since' => 1000000, 'until' => 1000000)) === array(1)
    && $ids(array('since' => '', 'until' => '')) === array(7, 6, 5, 4, 3, 2, 1));
check('history page: text search in an object name, case as typed, in Cyrillic', $ids(array('query' => 'шапк')) === array(2, 1) && $ids(array('query' => 'подвал')) === array(6, 5, 3));
check('history page: text search in the summary', $ids(array('query' => 'запись о пакете')) === array(7));
check('history page: wildcards in the search are literal', $ids(array('query' => '%')) === array() && $ids(array('query' => '_')) === array());
check('history page: filter by token', $ids(array('token_id' => $hTokenA['id'])) === array(6, 3, 2, 1) && $ids(array('token_id' => $hTokenB['id'])) === array(4)
    && $ids(array('token_id' => 999)) === array(7) && $ids(array('token_id' => (string) $hTokenA['id'])) === array(6, 3, 2, 1) && $ids(array('token_id' => 424242)) === array());
check('history page: the token filter combines with the other filters', $ids(array('token_id' => $hTokenA['id'], 'query' => 'подвал')) === array(6, 3)
    && $ids(array('token_id' => $hTokenA['id'], 'kind' => 'chunk', 'id' => $hHead['id'])) === array(2, 1) && $ids(array('token_id' => $hTokenB['id'], 'source' => 'external')) === array()
    && $ids(array('token_id' => $hTokenA['id'], 'status' => 'undone')) === array() && $ids(array('token_id' => $hTokenA['id']), 2, 1) === array(3, 2));
check('history page: an empty, zero or non-numeric token filter is no filter', $ids(array('token_id' => '')) === array(7, 6, 5, 4, 3, 2, 1) && $ids(array('token_id' => 0)) === array(7, 6, 5, 4, 3, 2, 1)
    && $ids(array('token_id' => 'abc')) === array(7, 6, 5, 4, 3, 2, 1));
check('history page: total counts the filtered changesets', $hService->changesets(array('token_id' => $hTokenA['id']), 1)['total'] === 4);
check('history page: the journal filters by token too', array_column($hDev->journal()->page(array('token_id' => $hTokenB['id']), 10, 0)['changesets'], 'id') === array(4));
$hTf = HistoryService::tokenFilter($hSite, (string) $hTokenA['id']);
check('history page: token filter of the URL names the token', $hTf === array('id' => $hTokenA['id'], 'label' => 'Claude Code') && HistoryService::tokenFilter($hSite, $hTokenB['id'])['label'] === 'Старый токен'
    && HistoryService::tokenFilter($hSite, '999') === array('id' => 999, 'label' => ''));
check('history page: a token filter that is not a positive integer is ignored', HistoryService::tokenFilter($hSite, 'abc') === null && HistoryService::tokenFilter($hSite, '0') === null && HistoryService::tokenFilter($hSite, '-1') === null
    && HistoryService::tokenFilter($hSite, '1 OR 1') === null && HistoryService::tokenFilter($hSite, '01') === null && HistoryService::tokenFilter($hSite, array('1')) === null && HistoryService::tokenFilter($hSite, null) === null);
throws('history api: modx_history has no token_id filter (unchanged)', ApiException::class, function () use ($call, $hDev, $hTokenA) { $call($hDev, 'history', array('token_id' => $hTokenA['id'])); });
check('history page: filters combine', $ids(array('source' => 'mcp', 'kind' => 'chunk', 'query' => 'подвал')) === array(6, 3));
$e = throws('history page: unknown source', ApiException::class, function () use ($hService) { $hService->changesets(array('source' => 'robot')); });
check('history page: unknown source is validation_failed', $e && $e->errorCode === 'validation_failed');

// paging
$hPageA = $hService->changesets(array(), 3, 0);
$hPageB = $hService->changesets(array(), 3, 3);
$hPageC = $hService->changesets(array(), 3, 6);
check('history page: paging keeps the total and the order', array_column($hPageA['changesets'], 'changeset_id') === array(7, 6, 5) && array_column($hPageB['changesets'], 'changeset_id') === array(4, 3, 2)
    && array_column($hPageC['changesets'], 'changeset_id') === array(1) && $hPageA['total'] === 7 && $hPageC['total'] === 7 && $hService->changesets(array('source' => 'mcp'), 2, 2)['total'] === 6
    && $hService->changesets(array(), 3, 50)['changesets'] === array());

// one changeset equals modx_history_diff, plus what the page needs
$hExtra = array_fill_keys(array('author', 'reversible', 'undone_by', 'undoes', 'not_reversible', 'notes'), true);
$hOne = $hService->changeset(2);
check('history page: changeset is the data of modx_history_diff', array_diff_key($hOne, $hExtra) === $call($hDev, 'history_diff', array('changeset_id' => 2))
    && $hOne['author'] === 'Claude Code' && $hOne['reversible'] === true && $hOne['undone_by'] === null && $hOne['objects'][0]['changed']['description']['new'] === 'первая правка');
$hNoChanges = $hService->changeset(7);
check('history page: a record without changes says why it cannot be undone', $hNoChanges['reversible'] === false && $hNoChanges['not_reversible'] === 'no_changes' && $hNoChanges['objects'] === array());
$e = throws('history page: unknown changeset', ApiException::class, function () use ($hService) { $hService->changeset(999); });
check('history page: unknown changeset is not_found', $e && $e->errorCode === 'not_found');

// undo: plan, conflict, force
$hHeadSecond = $call($hDev, 'update', array('kind' => 'chunk', 'id' => $hHead['id'], 'fields' => array('description' => 'вторая правка')));    // 8
$hPlan = $hService->undo(array('changeset_id' => 2));
check('history page: undo without confirm is a plan', $hPlan['performed'] === false && $hPlan['conflicts'] === 1 && $hPlan['objects'][0]['action'] === 'restore'
    && strpos($hPlan['objects'][0]['conflict'], 'changed later by changeset 8') === 0 && $hSite->row('modChunk', $hHead['id'])['description'] === 'вторая правка');
$e = throws('history page: a conflict stops a confirmed undo', ApiException::class, function () use ($hService) { $hService->undo(array('changeset_id' => 2), true); });
check('history page: undo_conflict with the plan in its details', $e && $e->errorCode === 'undo_conflict' && $e->details['conflicts'] === 1 && $hSite->row('modChunk', $hHead['id'])['description'] === 'вторая правка'
    && $hService->changesets(array('source' => 'manager'))['total'] === 0);
$hForced = $hService->undo(array('changeset_id' => 2), true, true);                                                                              // 9
check('history page: force undoes over the later change', $hForced['performed'] === true && $hForced['changeset_id'] === 9 && $hSite->row('modChunk', $hHead['id'])['description'] === '');
$hManagerRow = $hSite->pdo->query('SELECT source, user_id, token_id, session_id FROM modx_modxmcp_changesets WHERE id = 9')->fetch(PDO::FETCH_ASSOC);
check('history page: the undo is recorded as a manager changeset', $hManagerRow['source'] === 'manager' && (int) $hManagerRow['user_id'] === 2 && $hManagerRow['token_id'] === null && $hManagerRow['session_id'] === null);
$hMgr = $call($hDev, 'history', array('source' => 'manager'))['changesets'];
check('history page: modx_history shows it with the user name as author', count($hMgr) === 1 && $hMgr[0]['changeset_id'] === 9 && $hMgr[0]['author'] === 'Иванов' && $hMgr[0]['undoes'] === array(2) && $hMgr[0]['summary'] === 'undo changesets 2');
check('history page: the undone changeset links to its undo', $hService->changeset(2)['undone_by'] === 9 && $ids(array('status' => 'undone')) === array(2) && $hService->changeset(9)['undoes'] === array(2));
$e = throws('history page: an undone changeset cannot be undone again', ApiException::class, function () use ($hService) { $hService->undo(array('changeset_id' => 2), true); });
check('history page: that is not_reversible', $e && $e->errorCode === 'not_reversible');
$hSimple = $hService->undo(array('changeset_id' => 4), true);                                                                                    // 10
check('history page: undo of a creation removes the object', $hSimple['performed'] === true && $hSimple['objects'][0]['action'] === 'remove' && $hSite->getCount('modChunk', array('name' => 'sidebar')) === 0
    && $hService->changeset(10)['author'] === 'Иванов');
$e = throws('history page: a record without changes cannot be undone', ApiException::class, function () use ($hService) { $hService->undo(array('changeset_id' => 7), true); });
check('history page: that is not_reversible too', $e && $e->errorCode === 'not_reversible');
foreach (array(array(), array('changeset_id' => 1, 'to_checkpoint' => 1), array('changeset_id' => 0)) as $hBad) {
    $e = throws('history page: undo needs exactly one valid selector ' . json_encode($hBad), ApiException::class, function () use ($hService, $hBad) { $hService->undo($hBad); });
    check('history page: bad selector is validation_failed ' . json_encode($hBad), $e && $e->errorCode === 'validation_failed');
}
// redo: undoing the manager's undo brings the object back, as a manager changeset again
$hRedo = $hService->undo(array('changeset_id' => 10), true);                                                                                     // 11
check('history page: undo of a manager undo', $hRedo['performed'] === true && $hSite->getCount('modChunk', array('name' => 'sidebar')) === 1 && $hService->changeset(4)['undone_by'] === null && $hService->changeset(11)['author'] === 'Иванов');

// checkpoints, then a rollback to one
$hCps = $hService->checkpoints();
check('history page: checkpoints with label, author and counts', count($hCps['checkpoints']) === 1 && $hCps['checkpoints'][0]['checkpoint_id'] === $hCheckpoint['checkpoint_id']
    && $hCps['checkpoints'][0]['label'] === 'Перед работой' && $hCps['checkpoints'][0]['author'] === 'Claude Code' && $hCps['checkpoints'][0]['after'] === 7
    && $hCps['checkpoints'][0]['undoable_after'] === 5 && is_int($hCps['checkpoints'][0]['at']));
$hLater = $call($hDev, 'checkpoint', array('label' => 'Позже'));
$hCps = $hService->checkpoints()['checkpoints'];
check('history page: checkpoints newest first, a later one counts nothing yet', array_column($hCps, 'label') === array('Позже', 'Перед работой') && $hCps[0]['after'] === 0 && $hCps[0]['undoable_after'] === 0 && count($hService->checkpoints(1)['checkpoints']) === 1);
check('history page: a rollback to a checkpoint with nothing after it is empty', $hService->undo(array('to_checkpoint' => $hLater['checkpoint_id']))['changesets'] === array());
$hRollPlan = $hService->undo(array('to_checkpoint' => $hCheckpoint['checkpoint_id']));
check('history page: rollback plan, with conflicts', $hRollPlan['performed'] === false && $hRollPlan['conflicts'] >= 1 && count($hRollPlan['changesets']) === 5);
$e = throws('history page: rollback needs force over conflicts', ApiException::class, function () use ($hService, $hCheckpoint) { $hService->undo(array('to_checkpoint' => $hCheckpoint['checkpoint_id']), true); });
check('history page: rollback conflict is undo_conflict', $e && $e->errorCode === 'undo_conflict' && $hSite->getCount('modChunk', array('name' => 'шапка')) === 1);
$hRoll = $hService->undo(array('to_checkpoint' => $hCheckpoint['checkpoint_id']), true, true);
$hRollRow = $hSite->pdo->query('SELECT source, user_id, token_id FROM modx_modxmcp_changesets WHERE id = ' . (int) $hRoll['changeset_id'])->fetch(PDO::FETCH_ASSOC);
check('history page: rollback to a checkpoint is one manager changeset', $hRoll['performed'] === true && $hRollRow['source'] === 'manager' && (int) $hRollRow['user_id'] === 2 && $hRollRow['token_id'] === null
    && $hSite->getCount('modChunk', array('name' => 'шапка')) === 0 && $hSite->getCount('modChunk', array('name' => 'подвал')) === 0);

// the guards of the API apply to the page
$hSettingKind = $hAdmin->kinds->get('system_setting');
$hSite->store('modSystemSetting', array('key' => 'modxmcp.api_limit', 'value' => '50', 'xtype' => 'textfield', 'namespace' => 'modxmcp', 'area' => 'modxmcp:main'));
$hNow = ModxMCP\Journal\Snapshot::capture($hSite, $hSettingKind, 'modxmcp.api_limit');
$hOlder = $hNow;
$hOlder['fields']['value'] = '10';
foreach (array($hOlder, $hNow) as $hState) { $hAdmin->blobs()->put(ModxMCP\Journal\Snapshot::encode($hState)); }
$hOwnChange = $hAdmin->journal()->commit(array('source' => 'mcp', 'token_id' => 1, 'tool' => 'update', 'summary' => 'planted own setting'), array(array(
    'kind' => 'system_setting', 'object_key' => 'modxmcp.api_limit', 'label' => 'modxmcp.api_limit', 'op' => 'update',
    'before_revision' => ModxMCP\Journal\Snapshot::revision($hOlder), 'after_revision' => ModxMCP\Journal\Snapshot::revision($hNow), 'extra_blob' => null, 'reversible' => true, 'note' => '',
)));
$hSettingsBefore = $hSite->tableDump('modSystemSetting');
foreach (array(array(false, false), array(true, false), array(true, true)) as $hMode) {
    $e = throws('history page: a modxMCP setting is not restored from the page (' . json_encode($hMode) . ')', ApiException::class, function () use ($hService, $hOwnChange, $hMode) { $hService->undo(array('changeset_id' => $hOwnChange), $hMode[0], $hMode[1]); });
    check('history page: refusal is not_reversible with the explanation (' . json_encode($hMode) . ')', $e && $e->errorCode === 'not_reversible' && strpos($e->getMessage(), 'MODX manager') !== false);
}
check('history page: the refused undo changed nothing', $hSite->tableDump('modSystemSetting') === $hSettingsBefore);
// a rule of the Administrator group: planted as if an earlier allowed state of it had been journaled
$hSite->store('modAccessContext', array('id' => 77, 'target' => 'web', 'principal_class' => 'modUserGroup', 'principal' => 1, 'authority' => 9999, 'policy' => 2));
$hRuleKind = $hAdmin->kinds->get('context_access');
$hRuleNow = ModxMCP\Journal\Snapshot::capture($hSite, $hRuleKind, 77);
$hRuleOlder = $hRuleNow;
$hRuleOlder['fields']['authority'] = 5;
foreach (array($hRuleOlder, $hRuleNow) as $hState) { $hAdmin->blobs()->put(ModxMCP\Journal\Snapshot::encode($hState)); }
$hRuleChange = $hAdmin->journal()->commit(array('source' => 'mcp', 'token_id' => 1, 'tool' => 'update', 'summary' => 'planted admin rule'), array(array(
    'kind' => 'context_access', 'object_key' => '77', 'label' => 'web', 'op' => 'update',
    'before_revision' => ModxMCP\Journal\Snapshot::revision($hRuleOlder), 'after_revision' => ModxMCP\Journal\Snapshot::revision($hRuleNow), 'extra_blob' => null, 'reversible' => true, 'note' => '',
)));
$e = throws('history page: a rule of the Administrator group is not restored from the page', ApiException::class, function () use ($hService, $hRuleChange) { $hService->undo(array('changeset_id' => $hRuleChange), true, true); });
check('history page: that is not_reversible and nothing changed', $e && $e->errorCode === 'not_reversible' && strpos($e->getMessage(), 'Administrator group') !== false && $hSite->row('modAccessContext', 77)['authority'] === '9999');
// a user group undo the site-wide switch of the access group turns off
$hGroup = $call($hAdmin, 'create', array('kind' => 'user_group', 'fields' => array('name' => 'Редакторы')));
$hSite->options['modxmcp.disabled_groups'] = 'access';
$e = throws('history page: a site-wide disabled group still applies', ApiException::class, function () use ($hService, $hGroup) { $hService->undo(array('changeset_id' => $hGroup['changeset_id']), true, true); });
check('history page: undo into a disabled group is refused', $e instanceof ApiException && $hSite->getCount('modUserGroup', array('name' => 'Редакторы')) === 1);
$hSite->options['modxmcp.disabled_groups'] = '';

// the context for a manager user
$hContext = Context::forManager($hSite, $hSite->user, $hCore);
check('manager context: admin scope, no token, the user recorded', $hContext->managerUserId === 2 && $hContext->token['id'] === null && $hContext->token['scope'] === 'admin'
    && $hContext->token['label'] === 'manager: Иванов' && $hContext->token['plan_only'] === false && $hContext->token['denied_groups'] === array());
check('api context: no manager user by default', $hDev->managerUserId === null && $hAdmin->managerUserId === null);
$hAllowed = array('Context.php', 'Write/Transaction.php', 'Manager/HistoryService.php', 'Manager/Recorder.php');
$hFound = array();
foreach (new RecursiveIteratorIterator(new RecursiveDirectoryIterator($hCore . 'src', FilesystemIterator::SKIP_DOTS)) as $hFile) {
    if (substr($hFile->getFilename(), -4) !== '.php') { continue; }
    $hText = file_get_contents($hFile->getPathname());
    if (strpos($hText, 'managerUserId') !== false || strpos($hText, 'forManager') !== false) { $hFound[] = str_replace('\\', '/', substr($hFile->getPathname(), strlen($hCore . 'src/'))); }
}
sort($hFound);
sort($hAllowed);
check('manager context: only the context, the transaction and the service touch it, the kernel never does', $hFound === $hAllowed
    && strpos(file_get_contents($hCore . 'src/Kernel.php'), 'managerUserId') === false);

// --- Manager recorder: edits made by people in the manager are journaled as they happen ---
use ModxMCP\Manager\Recorder;
use ModxMCP\Write\Lock;
use ModxMCP\Write\Transaction;
$rCore = dirname(dirname(__DIR__)) . '/core/components/modxmcp/';
$rDir = realpath(sys_get_temp_dir()) . '/modxmcp-rec-' . bin2hex(random_bytes(6));
mkdir($rDir . '/core', 0700, true);
$rSite = fakeSite($rDir);
$rSite->options['modxmcp.auto_static'] = false;
$rSite->store('modUser', array('id' => 1, 'username' => 'admin', 'primary_group' => 0));
$rSite->store('modUser', array('id' => 2, 'username' => 'Иванов', 'primary_group' => 0));
$rPerson = $rSite->getObject('modUser', 2);
$rSite->user = $rPerson;
$rToken = (new TokenStore($rSite))->create('Claude Code', 'develop');
unset($rToken['token']);
$rDev = new Context($rSite, $rToken, $rCore, function () { throw new RuntimeException('no store in tests'); });
$rAdmin = new Context($rSite, array('scope' => 'admin') + $rToken, $rCore, function () { throw new RuntimeException('no store in tests'); });
$rSite->listeners[] = function ($name, array $params) use ($rSite) { Recorder::handle($rSite, $name, $params); };
$rService = new HistoryService($rSite, $rPerson);
$rLog = function () use ($rService) { return $rService->changesets(array(), 200)['changesets']; };
$rCount = function () use ($rLog) { return count($rLog()); };

// the same processors through the API: the recorder stays silent
$rHead = $call($rDev, 'create', array('kind' => 'chunk', 'fields' => array('name' => 'шапка', 'content' => "<h1>\nЗаголовок\n</h1>")));
$rApi = $call($rDev, 'update', array('kind' => 'chunk', 'id' => $rHead['id'], 'fields' => array('content' => "<h1>\nПравка API\n</h1>")));
$rEntries = $rLog();
check('recorder: an API create and update make exactly one changeset each, source mcp', count($rEntries) === 2 && $rEntries[0]['source'] === 'mcp' && $rEntries[1]['source'] === 'mcp'
    && $rEntries[0]['author'] === 'Claude Code' && Transaction::depth() === 0);

// a manager save of an existing chunk
$rSave = function (array $data) use ($rSite, $rHead) {
    return $rSite->runProcessor('element/chunk/update', $data + array('id' => $rHead['id'], 'name' => 'шапка', 'snippet' => "<h1>\nПравка API\n</h1>", 'description' => '', 'category' => 0, 'locked' => 0));
};
$rSave(array('snippet' => "<h1>\nПравка в админке\n</h1>", 'description' => 'человек'));
$rEntries = $rLog();
$rFirst = $rEntries[0];
check('recorder: a manager save is one changeset by the user', count($rEntries) === 3 && $rFirst['source'] === 'manager' && $rFirst['tool'] === 'manager' && $rFirst['author'] === 'Иванов'
    && $rFirst['summary'] === 'save chunk ' . $rHead['id'] . ' in the manager' && $rFirst['objects'][0]['op'] === 'update' && $rFirst['objects'][0]['name'] === 'шапка');
$rChange = (new \ModxMCP\Journal\Journal($rSite))->changeset($rFirst['changeset_id']);
check('recorder: the journal row has the user and no token', $rChange['user_id'] === 2 && $rChange['token_id'] === null && $rChange['source'] === 'manager');
$rDiff = $call($rDev, 'history_diff', array('changeset_id' => $rFirst['changeset_id']));
check('recorder: history_diff shows the changed fields and the before state is the API state', $rDiff['objects'][0]['changed']['content']['diff'] === "@@ -2,1 +2,1 @@\n-Правка API\n+Правка в админке"
    && $rDiff['objects'][0]['changed']['description']['new'] === 'человек');
check('recorder: modx_history shows the username as author', $call($rDev, 'history', array('kind' => 'chunk', 'id' => $rHead['id']))['changesets'][0]['author'] === 'Иванов');
check('recorder: no transaction is left open', Transaction::depth() === 0);
$rUndo = $call($rAdmin, 'undo', array('changeset_id' => $rFirst['changeset_id'], 'confirm' => true));
check('recorder: undo restores the state before the manager save', $rUndo['performed'] === true && $rSite->getObject('modChunk', array('id' => $rHead['id']))->get('snippet') === "<h1>\nПравка API\n</h1>"
    && $rSite->getObject('modChunk', array('id' => $rHead['id']))->get('description') === '');
check('recorder: the undo is one changeset of its own (the events it fires are ignored)', $rCount() === 4 && $rLog()[0]['tool'] === 'undo' && $rLog()[0]['undoes'] === array($rFirst['changeset_id']));

// the undo from the history page is silent too
$rService->undo(array('changeset_id' => $rLog()[0]['changeset_id']), true);
check('recorder: undo of an undo from HistoryService adds exactly one changeset', $rCount() === 5 && $rLog()[0]['tool'] === 'undo' && Transaction::depth() === 0);
$rSave(array('snippet' => "<h1>\nПравка API\n</h1>", 'description' => ''));   // put the chunk back to the API state; this is a manager save too
$rBase = $rCount();

// nothing changed: nothing recorded
$rSave(array());
check('recorder: a save that changes nothing records nothing', $rCount() === $rBase && Transaction::depth() === 0);

// a save refused after its before-event: nothing recorded; a later save is recorded correctly
$rSite->failBeforeSave = 'element/chunk/update';
$rSave(array('snippet' => 'не сохранится'));
$rSite->failBeforeSave = null;
check('recorder: a refused save records nothing', $rCount() === $rBase && $rSite->getObject('modChunk', array('id' => $rHead['id']))->get('snippet') !== 'не сохранится');
$rSave(array('snippet' => 'сохранится'));
$rLast = $rLog()[0];
$rLastDiff = $call($rDev, 'history_diff', array('changeset_id' => $rLast['changeset_id']));
check('recorder: the save after a refused one is recorded with the right before-state', $rCount() === $rBase + 1 && $rLast['source'] === 'manager'
    && $rLastDiff['objects'][0]['changed']['content']['diff'] === "@@ -1,3 +1,1 @@\n-<h1>\n-Правка API\n-</h1>\n+сохранится");
$rBase = $rCount();

// create and delete in the manager
$rSite->runProcessor('element/chunk/create', array('name' => 'новый', 'snippet' => 'тело'));
$rNew = $rSite->getObject('modChunk', array('name' => 'новый'));
$rNewId = (int) $rNew->get('id');
$rCreated = $rLog()[0];
check('recorder: a creation in the manager', $rCount() === $rBase + 1 && $rCreated['source'] === 'manager' && $rCreated['objects'][0]['op'] === 'create' && $rCreated['summary'] === "create chunk {$rNewId} in the manager"
    && $rCreated['author'] === 'Иванов');
$rTemplate = $call($rDev, 'create', array('kind' => 'template', 'fields' => array('name' => 'Основной', 'content' => '[[*content]]')));
$rTv = $call($rDev, 'create', array('kind' => 'tv', 'fields' => array('name' => 'hero', 'type' => 'image'), 'relations' => array('templates' => array($rTemplate['id']))));
$rSite->store('modTemplateVarResource', array('id' => 91, 'tmplvarid' => $rTv['id'], 'contentid' => 7, 'value' => 'hero.jpg'));
$rTvBefore = $call($rDev, 'get', array('kind' => 'tv', 'id' => $rTv['id']));
$rBase = $rCount();
$rSite->runProcessor('element/tv/remove', array('id' => $rTv['id']));
$rDeleted = $rLog()[0];
check('recorder: a deletion in the manager keeps the related rows', $rCount() === $rBase + 1 && $rDeleted['source'] === 'manager' && $rDeleted['objects'][0]['op'] === 'delete'
    && $rSite->getCount('modTemplateVarResource') === 0 && $rDeleted['summary'] === "delete tv {$rTv['id']} in the manager");
$rBack = $call($rAdmin, 'undo', array('changeset_id' => $rDeleted['changeset_id'], 'confirm' => true));
check('recorder: undo of a manager delete brings the object back with its id and rows', $rBack['performed'] === true
    && $call($rDev, 'get', array('kind' => 'tv', 'id' => $rTv['id']))['revision'] === $rTvBefore['revision'] && $rSite->getCount('modTemplateVarResource', array('value' => 'hero.jpg')) === 1);

// a resource delete in the manager trashes the descendants: all in one changeset
$rHome = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Главная', 'published' => true)));
$rAbout = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'О нас', 'parent' => $rHome['id'])));
$rTeam = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Команда', 'parent' => $rAbout['id'])));
$rBase = $rCount();
$rSite->runProcessor('resource/delete', array('id' => $rHome['id']));
$rTrash = $rLog()[0];
check('recorder: a resource delete in the manager is one changeset with the descendants', $rCount() === $rBase + 1 && $rTrash['source'] === 'manager' && count($rTrash['objects']) === 3
    && $rSite->getObject('modResource', array('id' => $rTeam['id']))->get('deleted') == 1);
$call($rAdmin, 'undo', array('changeset_id' => $rTrash['changeset_id'], 'confirm' => true));
check('recorder: and one undo restores all of them', $rSite->getObject('modResource', array('id' => $rTeam['id']))->get('deleted') == 0 && $rSite->getObject('modResource', array('id' => $rHome['id']))->get('deleted') == 0);

// a resource saved in the manager: created under a parent (its isfolder changes too) and edited
$rBase = $rCount();
$rSite->runProcessor('resource/create', array('pagetitle' => 'Новая', 'parent' => $rTeam['id'], 'class_key' => 'modDocument'));
$rNewPage = $rSite->getObject('modResource', array('pagetitle' => 'Новая'));
$rPageEntry = $rLog()[0];
$rKinds = array_map(function ($o) { return $o['kind'] . ':' . $o['id']; }, $rPageEntry['objects']);
sort($rKinds);
check('recorder: a resource created in the manager is journaled with the parent whose isfolder changed', $rCount() === $rBase + 1 && $rPageEntry['source'] === 'manager'
    && $rKinds === array('resource:' . $rTeam['id'], 'resource:' . $rNewPage->get('id')) && $rPageEntry['summary'] === 'create resource ' . $rNewPage->get('id') . ' in the manager');

// after-only events: publish from the tree
$rBase = $rCount();
$rSite->runProcessor('resource/unpublish', array('id' => $rHome['id']));
$rPub = $rLog()[0];
check('recorder: publishing from the tree is recorded as a manager change for a journaled resource', $rCount() === $rBase + 1 && $rPub['source'] === 'manager' && $rPub['author'] === 'Иванов'
    && $rPub['objects'][0]['op'] === 'update' && $rPub['summary'] === "resource {$rHome['id']} was changed in the manager");
$rSite->store('modResource', array('id' => 900, 'pagetitle' => 'Никогда не видела журнала', 'published' => 0, 'deleted' => 0, 'parent' => 0, 'content' => ''));
$rBase = $rCount();
$rSite->runProcessor('resource/publish', array('id' => 900));
check('recorder: publishing a resource the journal never saw records nothing and is no error', $rCount() === $rBase && Transaction::depth() === 0);

// the object was changed outside the journal before the manager save
$rSite->store('modChunk', array('description' => 'правка по FTP') + $rSite->row('modChunk', $rHead['id']));
$rBase = $rCount();
$rSave(array('snippet' => 'после FTP', 'description' => 'правка по FTP'));
$rTwo = array_slice($rLog(), 0, 2);
$rTwoDiff = $call($rDev, 'history_diff', array('changeset_id' => $rTwo[0]['changeset_id']));
check('recorder: an outside change before the manager save is its own changeset first', $rCount() === $rBase + 2 && $rTwo[1]['summary'] === "chunk {$rHead['id']} was changed outside the journal" && $rTwo[1]['source'] === 'external'
    && $rTwo[1]['author'] === 'unknown' && $rTwo[0]['source'] === 'manager' && $rTwo[0]['author'] === 'Иванов' && $rTwo[0]['summary'] === "save chunk {$rHead['id']} in the manager"
    && $rTwoDiff['objects'][0]['changed']['content']['diff'] === "@@ -1,1 +1,1 @@\n-сохранится\n+после FTP");
$rOutside = (new \ModxMCP\Journal\Journal($rSite))->changes(array($rTwo[1]['changeset_id']));
// It was made earlier by somebody unknown, not by the person who is saving now.
check('recorder: the earlier outside change keeps its "author unknown" note', $rOutside[0]['note'] !== '');

// an MCP lock on the object: the save succeeds, nothing is recorded, nothing is thrown
$rBase = $rCount();
$rLock = new Lock($rDev->dataDir() . '/locks');
$rLock->acquire('chunk:' . $rHead['id']);
$rLocked = $rSave(array('snippet' => 'пока блокировка', 'description' => 'правка по FTP'));
$rLock->releaseAll();
check('recorder: an MCP lock on the object skips recording, the save goes through', !$rLocked->isError() && $rCount() === $rBase && Transaction::depth() === 0
    && $rSite->getObject('modChunk', array('id' => $rHead['id']))->get('snippet') === 'пока блокировка');
$call($rDev, 'update', array('kind' => 'chunk', 'id' => $rHead['id'], 'fields' => array('description' => 'после блокировки')));
$rAfterLock = array_slice($rLog(), 0, 2);
check('recorder: a later API touch records the unrecorded change as outside', $rAfterLock[1]['source'] === 'external' && $rAfterLock[0]['source'] === 'mcp');

// settings and the user
$rBase = $rCount();
$rSite->options['modxmcp.history_track_manager'] = '0';
$rSave(array('snippet' => 'выключено', 'description' => 'после блокировки'));
$rOff = $rCount() === $rBase;
$rSite->options['modxmcp.history_track_manager'] = '1';
$rSite->user = $rSite->getObject('modUser', array('id' => 1000));
$rSave(array('snippet' => 'аноним', 'description' => 'после блокировки'));
$rAnon = $rCount() === $rBase;
$rSite->user = $rPerson;
$rSite->options['setup'] = true;
$rSave(array('snippet' => 'установка', 'description' => 'после блокировки'));
$rSetup = $rCount() === $rBase;
unset($rSite->options['setup']);
check('recorder: nothing is recorded with the setting off, without a logged-in user, or during setup', $rOff && $rAnon && $rSetup && Transaction::depth() === 0);
$rSite->context = new FakeObject($rSite, 'modContext', array('key' => 'web'), false);
$rSave(array('snippet' => 'фронтенд', 'description' => 'после блокировки'));
$rWeb = $rCount() === $rBase;
$rSite->context = new FakeObject($rSite, 'modContext', array('key' => 'mgr'), false);
$rSave(array('snippet' => 'менеджер', 'description' => 'после блокировки'));
// the unrecorded saves above are found as one outside change before this one is recorded
check('recorder: a web-context user is not a manager edit, the mgr context is', $rWeb && $rCount() === $rBase + 2 && $rLog()[0]['summary'] === "save chunk {$rHead['id']} in the manager" && $rLog()[1]['summary'] === "chunk {$rHead['id']} was changed outside the journal");
unset($rSite->context);
$rBase = $rCount();

// an error inside the recorder never reaches the caller
$rSite->pdo->exec('ALTER TABLE modx_modxmcp_changes RENAME TO modx_modxmcp_changes_away');
$rErrorLog = ini_set('error_log', '/dev/null');
$rBroken = $rSave(array('snippet' => 'журнал сломан', 'description' => 'после блокировки'));
ini_set('error_log', $rErrorLog);
$rSite->pdo->exec('ALTER TABLE modx_modxmcp_changes_away RENAME TO modx_modxmcp_changes');
check('recorder: a failing journal does not break the manager save', !$rBroken->isError() && $rSite->getObject('modChunk', array('id' => $rHead['id']))->get('snippet') === 'журнал сломан' && $rCount() === $rBase
    && Transaction::depth() === 0);

// events with parameters that only a real manager sends, fed to the recorder directly
$rCategory = $call($rDev, 'create', array('kind' => 'category', 'fields' => array('name' => 'Блоки')));
$rBase = $rCount();
$rCat = $rSite->getObject('modCategory', array('id' => $rCategory['id']));
Recorder::handle($rSite, 'OnCategoryBeforeSave', array('mode' => 'upd', 'category' => &$rCat, 'cacheFlag' => null));
$rCat->set('category', 'Блоки сайта');
$rCat->save();
Recorder::handle($rSite, 'OnCategorySave', array('mode' => 'upd', 'category' => &$rCat, 'cacheFlag' => null));
$rCatEntry = $rLog()[0];
check('recorder: a category saved by the model (object only, no id parameter)', $rCount() === $rBase + 1 && $rCatEntry['source'] === 'manager' && $rCatEntry['objects'][0]['kind'] === 'category' && $rCatEntry['objects'][0]['name'] === 'Блоки сайта');
Recorder::handle($rSite, 'OnCategoryBeforeRemove', array('category' => &$rCat, 'ancestors' => array()));
$rCat->remove();
Recorder::handle($rSite, 'OnCategoryRemove', array('category' => &$rCat, 'ancestors' => array()));
check('recorder: a category removed by the model', $rCount() === $rBase + 2 && $rLog()[0]['objects'][0]['op'] === 'delete');

$rA = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'A', 'menuindex' => 1)));
$rB = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'B', 'menuindex' => 2)));
$rBase = $rCount();
$rNodes = array(array('id' => (string) $rA['id'], 'context' => 'web', 'parent' => '0', 'order' => 1), array('id' => (string) $rB['id'], 'context' => 'web', 'parent' => '0', 'order' => 0), array('id' => '0'));
Recorder::handle($rSite, 'OnResourceBeforeSort', array('nodes' => &$rNodes, 'contexts' => array('web')));
foreach (array($rA['id'] => 2, $rB['id'] => 1) as $rId => $rIndex) { $rObject = $rSite->getObject('modResource', array('id' => $rId)); $rObject->set('menuindex', $rIndex); $rObject->save(); }
Recorder::handle($rSite, 'OnResourceSort', array('nodes' => &$rNodes, 'nodesAffected' => array(), 'contexts' => array('web'), 'contextsAffected' => array('web')));
$rSort = $rLog()[0];
check('recorder: a sort in the tree is one changeset with every moved resource', $rCount() === $rBase + 1 && $rSort['source'] === 'manager' && count($rSort['objects']) === 2 && $rSort['summary'] === 'sort resources in the manager');

// emptying the trash: the resources are gone after the event, so they are touched before it
$call($rDev, 'delete', array('kind' => 'resource', 'id' => $rA['id']));
$rBase = $rCount();
$rSite->runProcessor('resource/emptyrecyclebin', array());
$rEmpty = $rLog()[0];
check('recorder: emptying the trash journals every removed resource as deleted', $rCount() === $rBase + 1 && $rEmpty['source'] === 'manager' && $rEmpty['summary'] === 'empty the trash in the manager'
    && array_column($rEmpty['objects'], 'op') === array('delete') && $rSite->getCount('modResource', array('id' => $rA['id'])) === 0);
$rBackTrash = $call($rAdmin, 'undo', array('changeset_id' => $rEmpty['changeset_id'], 'confirm' => true));
check('recorder: and the removed resource can be brought back', $rBackTrash['performed'] === true && $rSite->getCount('modResource', array('id' => $rA['id'])) === 1);

// the API's own maintenance call is not a manager change, with the flag set by the kernel for the request
$rTrashed = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'в корзину', 'template' => 0)));
$call($rDev, 'delete', array('kind' => 'resource', 'id' => $rTrashed['id']));
$rBase = $rCount();
Kernel::servingApi(true);
$call($rAdmin, 'maintenance', array('operation' => 'empty_trash', 'confirm' => true));
Kernel::servingApi(false);
check('recorder: an API empty_trash is not journaled as a manager change', $rSite->getCount('modResource', array('id' => $rTrashed['id'])) === 0 && $rCount() === $rBase
    && !Kernel::servingApi());
$rTrashed = $call($rDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'в корзину 2', 'template' => 0)));
$call($rDev, 'delete', array('kind' => 'resource', 'id' => $rTrashed['id']));
$rBase = $rCount();
$rSite->runProcessor('resource/emptyrecyclebin', array());
check('recorder: without the flag the same processor is still recorded as a manager change', $rCount() === $rBase + 1 && $rLog()[0]['source'] === 'manager');
Kernel::servingApi(true);
$rToken2 = $rSite->getObject('modChunk', array('id' => $rHead['id']));
Recorder::handle($rSite, 'OnBeforeChunkFormSave', array('mode' => 'upd', 'id' => $rHead['id'], 'chunk' => &$rToken2));
check('recorder: while the API serves, handle() returns at once and opens nothing', Transaction::depth() === 0);
Kernel::servingApi(false);
check('recorder: the kernel sets the flag for the whole request', strpos(file_get_contents(dirname(__DIR__, 2) . '/core/components/modxmcp/src/Kernel.php'), 'self::servingApi(true);') !== false);

// more than 500 objects: skipped, one log line
$rMany = array();
for ($i = 1; $i <= 501; $i++) { $rMany[] = $i; }
$rBase = $rCount();
$rSite->pdo->exec('SELECT 1');
$rErrorLog = ini_set('error_log', $rDir . '/many.log');
Recorder::handle($rSite, 'OnBeforeEmptyTrash', array('ids' => &$rMany));
Recorder::handle($rSite, 'OnEmptyTrash', array('ids' => &$rMany));
ini_set('error_log', $rErrorLog);
check('recorder: above the cap nothing is recorded and one line is logged', $rCount() === $rBase && substr_count((string) @file_get_contents($rDir . '/many.log'), '[modxmcp]') === 1 && Transaction::depth() === 0);

// events and the plugin
$rExpected = array(
    'OnBeforeChunkFormSave', 'OnChunkFormSave', 'OnBeforeChunkFormDelete', 'OnChunkFormDelete',
    'OnBeforeSnipFormSave', 'OnSnipFormSave', 'OnBeforeSnipFormDelete', 'OnSnipFormDelete',
    'OnBeforeTempFormSave', 'OnTempFormSave', 'OnBeforeTempFormDelete', 'OnTempFormDelete',
    'OnBeforePluginFormSave', 'OnPluginFormSave', 'OnBeforePluginFormDelete', 'OnPluginFormDelete',
    'OnBeforeTVFormSave', 'OnTVFormSave', 'OnBeforeTVFormDelete', 'OnTVFormDelete',
    'OnCategoryBeforeSave', 'OnCategorySave', 'OnCategoryBeforeRemove', 'OnCategoryRemove',
    'OnBeforeDocFormSave', 'OnDocFormSave', 'OnBeforeDocFormDelete', 'OnDocFormDelete',
    'OnResourceUndelete', 'OnDocPublished', 'OnDocUnPublished', 'OnResourceBeforeSort', 'OnResourceSort', 'OnBeforeEmptyTrash', 'OnEmptyTrash',
    'OnBeforeUserFormSave', 'OnUserFormSave', 'OnBeforeUserFormDelete', 'OnUserFormDelete', 'OnUserActivate', 'OnUserDeactivate',
    'OnMediaSourceBeforeFormSave', 'OnMediaSourceFormSave', 'OnMediaSourceBeforeFormDelete', 'OnMediaSourceFormDelete',
    'OnContextBeforeSave', 'OnContextSave', 'OnContextBeforeRemove', 'OnContextRemove',
);
$rEvents = Recorder::events();
$rSorted = $rEvents;
sort($rSorted);
$rWanted = $rExpected;
sort($rWanted);
$rWantedPlugin = array_merge($rWanted, array('OnWebPageInit'));
sort($rWantedPlugin);
check('recorder: events() lists every event of the table exactly once', $rSorted === $rWanted && count($rEvents) === count(array_unique($rEvents)));

$rJournalBefore = $rCount();
$rFirstSync = Recorder::syncPlugin($rSite);
$rPlugin = $rSite->getObject('modPlugin', array('name' => 'modxMCP'));
$rNames = function ($id) use ($rSite) { $n = array(); foreach ($rSite->getCollection('modPluginEvent', array('pluginid' => $id)) as $row) { $n[] = $row->get('event'); } sort($n); return $n; };
check('syncPlugin: creates the plugin with exactly the events of the recorder', $rFirstSync['created'] === true && $rPlugin && $rNames($rPlugin->get('id')) === $rWantedPlugin
    && strpos((string) $rPlugin->get('plugincode'), 'Recorder::handle') !== false && strpos((string) $rPlugin->get('plugincode'), '<?php') === false
    && $rPlugin->get('description') === 'Records changes made in the manager into the modxMCP journal.');
$rSecondSync = Recorder::syncPlugin($rSite);
check('syncPlugin: is idempotent', $rSecondSync === array('created' => false, 'added' => array(), 'removed' => array()) && $rSite->getCount('modPlugin', array('name' => 'modxMCP')) === 1 && count($rNames($rPlugin->get('id'))) === count($rWantedPlugin));
$rSite->store('modPlugin', array('id' => 70, 'name' => 'tracker', 'plugincode' => 'return;'));
$rSite->store('modPluginEvent', array('id' => 71, 'pluginid' => 70, 'event' => 'OnWebPagePrerender', 'priority' => 0, 'propertyset' => 0));
$rSite->store('modPluginEvent', array('id' => 72, 'pluginid' => $rPlugin->get('id'), 'event' => 'OnWebPagePrerender', 'priority' => 0, 'propertyset' => 0));
$rSite->getObject('modPluginEvent', array('pluginid' => $rPlugin->get('id'), 'event' => 'OnDocPublished'))->remove();
$rThird = Recorder::syncPlugin($rSite);
check('syncPlugin: adds missing events, removes events no longer listed, leaves other plugins alone', $rThird['added'] === array('OnDocPublished') && $rThird['removed'] === array('OnWebPagePrerender')
    && $rNames($rPlugin->get('id')) === $rWantedPlugin && $rSite->getCount('modPluginEvent', array('pluginid' => 70)) === 1 && $rSite->getObject('modPlugin', array('id' => 70))->get('plugincode') === 'return;');
check('syncPlugin: leaves no journal entries and the plugin is not a recorded kind object', $rCount() === $rJournalBefore
    && (new \ModxMCP\Journal\Journal($rSite))->lastChange('plugin', (string) $rPlugin->get('id')) === null && Transaction::depth() === 0);

// the plugin file is a thin call into the recorder
$rPluginCode = Recorder::pluginCode($rCore);
$rSite->event = (object) array('name' => 'OnChunkFormSave');
$rProps = array();
$rRan = (function ($modx, $scriptProperties) use ($rPluginCode) { eval($rPluginCode); return true; })($rSite, $rProps);
check('plugin file: runs against the component and is a few lines', $rRan === true && substr_count($rPluginCode, "\n") <= 6);
unset($rSite->event);

// --- Open in the manager ---
$oDir = realpath(sys_get_temp_dir()) . '/modxmcp-open-' . bin2hex(random_bytes(6));
mkdir($oDir . '/core', 0700, true);
$oSite = fakeSite($oDir);
$oSite->options['modxmcp.auto_static'] = false;
$oSite->store('modUser', array('id' => 601, 'username' => 'Редактор', 'primary_group' => 0));
$oSite->store('modUser', array('id' => 602, 'username' => 'service', 'primary_group' => 0));
$oSite->store('modResource', array('id' => 9, 'pagetitle' => 'placeholder', 'context_key' => 'web', 'content' => ''));
$oCtx = function ($scope = 'develop') use ($oSite, $dev) { return new Context($oSite, array('scope' => $scope) + $dev->token, $dev->corePath, function () { throw new RuntimeException('no store'); }); };
$oText = "Текст страницы\nвторая строка";
$oMake = function ($title) use ($call, $oCtx, $oText) { return $call($oCtx(), 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => $title, 'content' => $oText)))['id']; };
$oChunk = $call($oCtx(), 'create', array('kind' => 'chunk', 'fields' => array('name' => 'блок', 'content' => 'один')))['id'];
$oA = $oMake('Страница А');
$oB = $oMake('Страница Б');
$oC = $oMake('Страница В');
$oD = $oMake('Страница Г');
check('open: the chunk id is not a resource id', $oChunk === 1 && $oSite->getCount('modResource', array('id' => $oChunk)) === 0);
$oContent = function ($id) use ($oSite) { return $oSite->getObject('modResource', $id)->get('content'); };
$oLocked = function ($label, callable $fn) {
    $e = throws($label, ApiException::class, $fn);
    check($label . ': locked, 409, open_in_manager with the person', $e && $e->errorCode === 'locked' && $e->httpStatus === 409 && $e->details['reason'] === 'open_in_manager'
        && $e->details['user_id'] === 601 && $e->details['username'] === 'Редактор' && strpos($e->getMessage(), 'Редактор') !== false && strpos($e->getMessage(), 'force:true') !== false);
    return $e;
};

// a lock is only read: the kind leaves it in place and unlocked resources answer null
$oSite->lockResource($oA, 601);
$oKind = $oCtx()->kinds->get('resource');
check('open: openInManager reads twice and leaves the lock', $oKind->openInManager($oSite, $oA) === array('user_id' => 601, 'username' => 'Редактор')
    && $oKind->openInManager($oSite, $oA) === array('user_id' => 601, 'username' => 'Редактор') && $oSite->resourceLock($oA) === 601
    && $oKind->openInManager($oSite, $oB) === null && $oCtx()->kinds->get('chunk')->openInManager($oSite, $oChunk) === null);

// update
$oLocked('open: update', function () use ($call, $oCtx, $oA) { $call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oA, 'fields' => array('longtitle' => 'Новый'))); });
check('open: refused update changed nothing', $oSite->getObject('modResource', $oA)->get('longtitle') !== 'Новый');
$call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oB, 'fields' => array('longtitle' => 'Новый')));
check('open: an unlocked resource is updated', $oSite->getObject('modResource', $oB)->get('longtitle') === 'Новый');
$oForce = $oCtx();
$oForced = $call($oForce, 'update', array('kind' => 'resource', 'id' => $oA, 'fields' => array('longtitle' => 'Новый'), 'force' => true));
check('open: force writes with a warning', $oForced['changed'] === array('longtitle') && count($oForce->warnings) === 1 && strpos($oForce->warnings[0], 'Редактор') !== false);
$oDry = $call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oA, 'fields' => array('longtitle' => 'Другой'), 'dry_run' => true));
check('open: a dry run reports and does not throw', $oDry['dry_run'] === true && $oDry['open_in_manager'] === array('user_id' => 601, 'username' => 'Редактор')
    && $oSite->getObject('modResource', $oA)->get('longtitle') === 'Новый'
    && !isset($call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oB, 'fields' => array('longtitle' => 'Другой'), 'dry_run' => true))['open_in_manager']));

// edit_code
$oLocked('open: edit_code', function () use ($call, $oCtx, $oA) { $call($oCtx(), 'edit_code', array('kind' => 'resource', 'id' => $oA, 'edits' => array(array('start_line' => 1, 'replacement' => 'Правка')))); });
check('open: refused edit_code changed nothing', $oContent($oA) === $oText);
check('open: edit_code passes unlocked, with force, and the dry run reports',
    $call($oCtx(), 'edit_code', array('kind' => 'resource', 'id' => $oB, 'edits' => array(array('start_line' => 1, 'replacement' => 'Правка'))))['changed'] === array('content')
    && $call($oCtx(), 'edit_code', array('kind' => 'resource', 'id' => $oA, 'edits' => array(array('start_line' => 1, 'replacement' => 'Правка')), 'force' => true))['changed'] === array('content')
    && $call($oCtx(), 'edit_code', array('kind' => 'resource', 'id' => $oA, 'edits' => array(array('start_line' => 2, 'replacement' => 'ещё')), 'dry_run' => true))['open_in_manager']['username'] === 'Редактор'
    && $oContent($oA) === "Правка\nвторая строка");

// delete
$oLocked('open: delete', function () use ($call, $oCtx, $oA) { $call($oCtx(), 'delete', array('kind' => 'resource', 'id' => $oA)); });
$oDelDry = $call($oCtx(), 'delete', array('kind' => 'resource', 'id' => $oA, 'dry_run' => true));
check('open: refused delete left the page, the dry run reports', $oSite->getObject('modResource', $oA)->get('deleted') != 1 && $oDelDry['open_in_manager']['user_id'] === 601 && isset($oDelDry['would_delete']));
$call($oCtx(), 'delete', array('kind' => 'resource', 'id' => $oD));
check('open: delete passes unlocked', $oSite->getObject('modResource', $oD)->get('deleted') == 1);
$oD = $oMake('Страница Д');

// replace (one changeset: an open object stops all of it)
$oReplace = array('find' => 'Текст', 'replacement' => 'Текстик', 'kinds' => array('resource'));
$oSite->unlockResource($oA);
$oSite->lockResource($oC, 601);
$oPlan = $call($oCtx(), 'replace', $oReplace + array('dry_run' => true));
$oOpenRows = array();
foreach ($oPlan['objects'] as $row) { $oOpenRows[$row['id']] = isset($row['open_in_manager']); }
check('open: the replace dry run marks the open page only', $oOpenRows[$oC] === true && $oOpenRows[$oD] === false && count($oPlan['objects']) >= 2);
$oLocked('open: replace', function () use ($call, $oCtx, $oReplace, $oPlan) { $call($oCtx(), 'replace', $oReplace + array('expected_revisions' => (array) $oPlan['revisions'])); });
check('open: refused replace changed no page', $oContent($oC) === $oText && $oContent($oD) === $oText);
$oRepForce = $oCtx();
$oRep = $call($oRepForce, 'replace', $oReplace + array('expected_revisions' => (array) $oPlan['revisions'], 'force' => true));
check('open: replace with force goes through with a warning', $oRep['total_occurrences'] >= 2 && strpos($oContent($oC), 'Текстик') === 0 && count($oRepForce->warnings) === 1);
$oSite->unlockResource($oC);

// bulk: all or nothing, so one open page stops the whole operation and names it
$oSite->lockResource($oC, 601);
$oLocked('open: bulk_resources', function () use ($call, $oCtx, $oB, $oC) { $call($oCtx(), 'bulk_resources', array('operation' => 'publish', 'ids' => array($oB, $oC))); });
check('open: refused bulk changed nothing, not even the unlocked page', $oSite->getObject('modResource', $oB)->get('published') != 1 && $oSite->getObject('modResource', $oC)->get('published') != 1);
$oBulkErr = throws('open: bulk names every open page', ApiException::class, function () use ($call, $oCtx, $oB, $oC) { $call($oCtx(), 'bulk_resources', array('operation' => 'publish', 'ids' => array($oB, $oC))); });
check('open: bulk details list the open pages', $oBulkErr->details['items'] === array(array('id' => $oC, 'user_id' => 601, 'username' => 'Редактор')));
$oBulkDry = $call($oCtx(), 'bulk_resources', array('operation' => 'publish', 'ids' => array($oB, $oC), 'dry_run' => true));
check('open: bulk dry run marks the open page', !isset($oBulkDry['objects'][0]['open_in_manager']) && $oBulkDry['objects'][1]['open_in_manager']['user_id'] === 601);
$oBulkForce = $oCtx();
$call($oBulkForce, 'bulk_resources', array('operation' => 'publish', 'ids' => array($oB, $oC), 'force' => true));
check('open: bulk with force publishes both and warns', $oSite->getObject('modResource', $oB)->get('published') == 1 && $oSite->getObject('modResource', $oC)->get('published') == 1 && count($oBulkForce->warnings) === 1);
$oSite->unlockResource($oC);
$call($oCtx(), 'bulk_resources', array('operation' => 'unpublish', 'ids' => array($oB, $oC)));
check('open: bulk passes when nothing is open', $oSite->getObject('modResource', $oB)->get('published') != 1);

// the kind chunk is never affected, and a lock owned by the service user still blocks
$oSite->lockResource($oChunk, 601);
$oChunkDry = $call($oCtx(), 'delete', array('kind' => 'chunk', 'id' => $oChunk, 'dry_run' => true));
check('open: a chunk is never refused', $call($oCtx(), 'update', array('kind' => 'chunk', 'id' => $oChunk, 'fields' => array('description' => 'ok')))['changed'] === array('description')
    && $oChunkDry['dry_run'] === true && !isset($oChunkDry['open_in_manager']));
$oSite->unlockResource($oChunk);
$oSite->user = $oSite->getObject('modUser', 602);
$oSite->lockResource($oB, 602);
$e = throws('open: a lock of the service user itself', ApiException::class, function () use ($call, $oCtx, $oB) { $call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oB, 'fields' => array('longtitle' => 'Сервис'))); });
check('open: the service user\'s lock still blocks', $e && $e->errorCode === 'locked' && $e->details['user_id'] === 602 && $e->details['username'] === 'service');
$oSite->unlockResource($oB);
$call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oB, 'fields' => array('longtitle' => 'Сервис')));
$oSite->user = null;

// undo: a conflict in the plan, refused without force, done with it
$oEdit = $call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oB, 'fields' => array('longtitle' => 'До отмены')));
$oSite->lockResource($oB, 601);
$oUndoPlan = $call($oCtx(), 'undo', array('changeset_id' => $oEdit['changeset_id']));
check('open: undo plans a conflict that names the person', $oUndoPlan['conflicts'] === 1 && $oUndoPlan['performed'] === false && $oUndoPlan['objects'][0]['conflict'] === 'open in the manager by Редактор');
$e = throws('open: undo confirm without force', ApiException::class, function () use ($call, $oCtx, $oEdit) { $call($oCtx(), 'undo', array('changeset_id' => $oEdit['changeset_id'], 'confirm' => true)); });
check('open: undo is refused with undo_conflict and nothing changed', $e && $e->errorCode === 'undo_conflict' && $oSite->getObject('modResource', $oB)->get('longtitle') === 'До отмены');
$oUndoForce = $oCtx();
$oDone = $call($oUndoForce, 'undo', array('changeset_id' => $oEdit['changeset_id'], 'confirm' => true, 'force' => true));
check('open: undo with force is done, with a warning', $oDone['performed'] === true && $oSite->getObject('modResource', $oB)->get('longtitle') === 'Сервис' && count($oUndoForce->warnings) === 1);
$oSite->unlockResource($oB);
$oEdit2 = $call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oB, 'fields' => array('longtitle' => 'Ещё раз')));
check('open: undo of an unlocked page has no conflict', $call($oCtx(), 'undo', array('changeset_id' => $oEdit2['changeset_id']))['conflicts'] === 0);

// the force argument: on the write tools that can meet an open page, with the old meaning on undo, and not on file tools
$oForceTools = array();
foreach (array('update', 'edit_code', 'delete', 'replace', 'bulk_resources', 'invoke', 'undo', 'write_file') as $oTool) {
    $oForceTools[$oTool] = isset($oCtx()->actions->get($oTool)->inputSchema()['properties']['force']);
}
check('open: force is accepted exactly where it applies', $oForceTools === array('update' => true, 'edit_code' => true, 'delete' => true, 'replace' => true, 'bulk_resources' => true, 'invoke' => true, 'undo' => true, 'write_file' => false));
check('open: undo keeps the meaning of its own force', strpos($oCtx()->actions->get('undo')->inputSchema()['properties']['force']['description'], 'Undo even over later changes') === 0);

// the lock between two MCP requests keeps its code and says why
$oLockDir = $oDir . '/locks';
$oFirst = new \ModxMCP\Write\Lock($oLockDir);
$oFirst->acquire('resource:1');
$e = throws('open: a second MCP request on the same object', ApiException::class, function () use ($oLockDir) { (new \ModxMCP\Write\Lock($oLockDir))->acquire('resource:1'); });
check('open: the MCP lock is locked with reason mcp_request', $e && $e->errorCode === 'locked' && $e->details['reason'] === 'mcp_request');
$oFirst->releaseAll();

// the manager recorder never asks whether a page is open
$oRecorderSource = '';
foreach (glob($oCtx()->corePath . 'src/Manager/*.php') as $oFile) { $oRecorderSource .= file_get_contents($oFile); }
check('open: the manager recorder does not call assertNotOpen', $oRecorderSource !== '' && strpos($oRecorderSource, 'assertNotOpen') === false && strpos($oRecorderSource, 'openInManager') === false);

// MODX's resource delete processor locks every child and never unlocks it. The API call must not leave those locks
// behind (they would read as "open in the manager" by the service user for lock_ttl and block the next write or undo),
// but a lock that a person held before the call stays.
$oUserBefore = $oSite->user;
$oSite->user = new FakeObject($oSite, 'modUser', array('id' => 602, 'username' => 'service', 'active' => 1), false);
$oFolder = $oMake('Папка');
$oKid1 = $call($oCtx(), 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Дочерняя 1', 'parent' => $oFolder, 'content' => 'x')))['id'];
$oKid2 = $call($oCtx(), 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Дочерняя 2', 'parent' => $oFolder, 'content' => 'x')))['id'];
$oSite->lockResource($oKid2, 601);
$oDel = $call($oCtx(), 'delete', array('kind' => 'resource', 'id' => $oFolder));
check('locks: an API delete leaves no lock of its own on the children', $oSite->getObject('modResource', $oKid1)->get('deleted') == 1 && $oSite->resourceLock($oKid1) === 0);
check('locks: a lock a person held before the call is kept', $oSite->resourceLock($oKid2) === 601);
$oSite->unlockResource($oKid2);
$oUndo = $call($oCtx(), 'undo', array('changeset_id' => $oDel['changeset_id'], 'confirm' => true));
check('locks: so the delete can be undone at once, without force', $oUndo['performed'] === true && $oUndo['conflicts'] === 0
    && $oSite->getObject('modResource', $oKid1)->get('deleted') == 0 && $oSite->resourceLock($oKid1) === 0);
$oSite->lockResource($oKid1, 602);
$e = throws('locks: a lock of the service user that existed before the call still blocks', ApiException::class, function () use ($call, $oCtx, $oKid1) {
    $call($oCtx(), 'update', array('kind' => 'resource', 'id' => $oKid1, 'fields' => array('longtitle' => 'x')));
});
check('locks: and it is kept', $e && $e->details['reason'] === 'open_in_manager' && $oSite->resourceLock($oKid1) === 602);
$oSite->unlockResource($oKid1);
$oSite->user = $oUserBefore;

// --- Site audit ---
use ModxMCP\Verify\SiteAudit;
$aDir = realpath(sys_get_temp_dir()) . '/modxmcp-audit-' . bin2hex(random_bytes(6));
mkdir($aDir . '/core/elements/chunks', 0700, true);
$aSite = fakeSite($aDir);
$aRead = new Context($aSite, array('scope' => 'read') + $dev->token, $dev->corePath, function () { throw new RuntimeException('no store'); });

// the empty site first: no findings, zero counts
$aEmpty = $call($aRead, 'audit_site');
check('audit: an empty site has no findings and zero counts', $aEmpty['findings'] === array() && array_keys($aEmpty['summary']) === SiteAudit::CHECKS
    && array_sum(array_column($aEmpty['summary'], 'count')) === 0 && array_sum(array_column($aEmpty['summary'], 'truncated')) === 0);

$aEl = function ($class, array $row) use ($aSite) {
    static $ids = array();
    $ids[$class] = isset($ids[$class]) ? $ids[$class] + 1 : 1;
    $aSite->store($class, $row + array('id' => $ids[$class], 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => ''));
    return $ids[$class];
};
$aSite->store('modContext', array('key' => 'web', 'name' => 'Web'));
$aSite->store('modContext', array('key' => 'second', 'name' => 'Second'));
file_put_contents($aDir . '/core/elements/chunks/ok.tpl', 'Файл на месте');
// templates: 1 is used by pages, 2 by none
$aSite->store('modTemplate', array('id' => 1, 'templatename' => 'Базовый', 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => '', 'icon' => '',
    'content' => '[[$head]] [[mainMenu]] [[badsnip]] [[$gone]] [[$linkbox]] [[$staticok]] [[$staticgone]] [[*sub]]'));
$aSite->store('modTemplate', array('id' => 2, 'templatename' => 'Пустой шаблон', 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => '', 'icon' => '', 'content' => 'x'));
// chunks
$aEl('modChunk', array('name' => 'head', 'snippet' => '<h1>Заголовок</h1>'));
$aEl('modChunk', array('name' => 'unusedChunk', 'snippet' => 'Никем не используется'));
$aEl('modChunk', array('name' => 'linkbox', 'snippet' => 'Ссылка [[~6]] на удалённую страницу'));
$aEl('modChunk', array('name' => 'staticok', 'snippet' => '', 'static' => 1, 'static_file' => '[[++core_path]]elements/chunks/ok.tpl'));
$aEl('modChunk', array('name' => 'staticgone', 'snippet' => 'запасной', 'static' => 1, 'static_file' => '[[++core_path]]elements/chunks/gone.tpl'));
// snippets and plugins
$aEl('modSnippet', array('name' => 'mainMenu', 'snippet' => "return 'Привет';"));
$aEl('modSnippet', array('name' => 'badsnip', 'snippet' => "return 'Привет' (;"));
$aEl('modPlugin', array('name' => 'goodplugin', 'plugincode' => 'return;', 'disabled' => 0));
$aEl('modPlugin', array('name' => 'badplugin', 'plugincode' => "\$x = ;\n", 'disabled' => 1));
// a TV that a template has, and one nothing has
$aSite->store('modTemplateVar', array('id' => 1, 'name' => 'sub', 'default_text' => '', 'caption' => '', 'type' => 'text', 'category' => 0, 'static' => 0, 'static_file' => ''));
$aSite->store('modTemplateVar', array('id' => 2, 'name' => 'orphanTv', 'default_text' => '', 'caption' => '', 'type' => 'text', 'category' => 0, 'static' => 0, 'static_file' => ''));
$aSite->store('modTemplateVarTemplate', array('tmplvarid' => 1, 'templateid' => 1, 'rank' => 0));
// resources
$aRes = function ($id, $title, array $more = array()) use ($aSite) {
    $aSite->store('modResource', $more + array('id' => $id, 'pagetitle' => $title, 'context_key' => 'web', 'template' => 1, 'published' => 1, 'deleted' => 0, 'uri' => 'p' . $id . '.html', 'content' => '', 'editedon' => $id));
};
$aRes(1, 'Главная', array('content' => 'Ссылки: [[~2]] и [[~99? &scheme=`full`]]', 'uri' => 'index.html'));
$aRes(2, 'О нас', array('content' => 'См. [[~5]]', 'uri' => 'about.html'));
$aRes(3, 'Дубль А', array('uri' => 'dup.html'));
$aRes(4, 'Дубль Б', array('uri' => 'dup.html'));
$aRes(5, 'Скрытая', array('published' => 0, 'uri' => 'hidden.html'));
$aRes(6, 'Удалённая страница', array('deleted' => 1, 'uri' => 'dup.html', 'template' => 78));
$aRes(7, 'Другой контекст', array('context_key' => 'second', 'uri' => 'dup.html'));
$aRes(8, 'Без шаблона', array('template' => 77));
$aStateBefore = array($aSite->tableDump('modResource'), $aSite->tableDump('modChunk'), $aSite->tableDump('modSnippet'), $aSite->tableDump('modPlugin'));
$aJournalBefore = count($call($aRead, 'history', array('limit' => 100))['changesets']);

$audit = $call($aRead, 'audit_site');
$aBy = array();
foreach ($audit['findings'] as $finding) { $aBy[$finding['check']][] = $finding; }
$aOne = function ($check) use ($aBy) { return isset($aBy[$check]) && count($aBy[$check]) === 1 ? $aBy[$check][0] : null; };
check('audit: summary counts every problem exactly once', array_column($audit['summary'], 'count') === array(3, 1, 3, 1, 1, 2, 1, 0, 0) && array_keys($audit['summary']) === SiteAudit::CHECKS
    && count($audit['findings']) === 12 && array_sum(array_column($audit['summary'], 'truncated')) === 0);
check('audit: findings come in the order of the checks', array_values(array_unique(array_column($audit['findings'], 'check'))) === array('broken_link', 'missing_element', 'unused_element', 'static_file_missing', 'duplicate_alias', 'php_syntax', 'missing_template'));

$aLinks = array();
foreach ($aBy['broken_link'] as $finding) { $aLinks[$finding['kind'] . ':' . $finding['id']] = $finding; }
check('audit: a link to a missing page is an error with the target', $aLinks['resource:1']['severity'] === 'error' && $aLinks['resource:1']['name'] === 'Главная'
    && $aLinks['resource:1']['details'] === array('target' => 99, 'exists' => false) && strpos($aLinks['resource:1']['message'], '[[~99]]') !== false);
check('audit: a link to an unpublished page is a warning', $aLinks['resource:2']['severity'] === 'warning' && $aLinks['resource:2']['details']['target'] === 5
    && $aLinks['resource:2']['details']['published'] === false && $aLinks['resource:2']['details']['deleted'] === false);
check('audit: a link in an element, to a deleted page, is a warning', $aLinks['chunk:3']['severity'] === 'warning' && $aLinks['chunk:3']['name'] === 'linkbox'
    && $aLinks['chunk:3']['details']['deleted'] === true && $aLinks['chunk:3']['details']['target'] === 6 && !isset($aLinks['resource:3']));
$f = $aOne('missing_element');
check('audit: a call of a missing chunk names the caller', $f && $f['severity'] === 'error' && $f['kind'] === 'template' && $f['id'] === 1 && $f['name'] === 'Базовый'
    && $f['details'] === array('calls' => 'chunk', 'missing' => 'gone'));
$aUnused = array();
foreach ($aBy['unused_element'] as $finding) { $aUnused[$finding['kind'] . ':' . $finding['name']] = $finding; }
check('audit: unused chunk, TV and template, and nothing used', array_keys($aUnused) === array('template:Пустой шаблон', 'chunk:unusedChunk', 'tv:orphanTv')
    && $aUnused['chunk:unusedChunk']['severity'] === 'info' && $aUnused['template:Пустой шаблон']['id'] === 2 && $aUnused['tv:orphanTv']['id'] === 2);
$f = $aOne('static_file_missing');
check('audit: a static element whose file is gone', $f && $f['severity'] === 'error' && $f['kind'] === 'chunk' && $f['name'] === 'staticgone'
    && $f['details'] === array('static_file' => '[[++core_path]]elements/chunks/gone.tpl', 'reason' => 'missing') && $audit['summary']['static_file_missing']['scanned'] === 2);
$f = $aOne('duplicate_alias');
check('audit: a shared address is reported once with every id, deleted pages and other contexts left out', $f && $f['severity'] === 'warning' && $f['kind'] === 'resource' && $f['id'] === 3
    && $f['details'] === array('uri' => 'dup.html', 'context' => 'web', 'ids' => array(3, 4)));
$aSyntax = array();
foreach ($aBy['php_syntax'] as $finding) { $aSyntax[$finding['name']] = $finding; }
check('audit: broken snippet and disabled plugin with line and message', array_keys($aSyntax) === array('badsnip', 'badplugin') && $aSyntax['badsnip']['severity'] === 'error'
    && $aSyntax['badsnip']['kind'] === 'snippet' && $aSyntax['badsnip']['details']['line'] === 1 && $aSyntax['badsnip']['details']['error'] !== ''
    && $aSyntax['badplugin']['kind'] === 'plugin' && $aSyntax['badplugin']['details']['disabled'] === true && $aSyntax['badplugin']['details']['line'] === 1
    && $audit['summary']['php_syntax']['scanned'] === 4);
$f = $aOne('missing_template');
check('audit: a live page with a missing template, not the deleted one', $f && $f['severity'] === 'error' && $f['id'] === 8 && $f['name'] === 'Без шаблона' && $f['details'] === array('template' => 77)
    && $audit['summary']['missing_template']['scanned'] === 7);
check('audit: scanned counts and the rules in the notes', $audit['summary']['broken_link']['scanned'] === 7 + (5 + 2 + 2 + 2) && $audit['summary']['unused_element']['scanned'] === 5 + 2 + 2 + 2
    && count(array_filter($audit['notes'], function ($note) { return strpos($note, 'unused_element follows the dependency graph') === 0; })) === 1);
check('audit: read-only, nothing changed and nothing journaled', array($aSite->tableDump('modResource'), $aSite->tableDump('modChunk'), $aSite->tableDump('modSnippet'), $aSite->tableDump('modPlugin')) === $aStateBefore
    && count($call($aRead, 'history', array('limit' => 100))['changesets']) === $aJournalBefore);

// the checks filter and the limit
$aFilter = $call($aRead, 'audit_site', array('checks' => array('duplicate_alias', 'missing_template')));
check('audit: checks limit what is run and reported', array_keys($aFilter['summary']) === array('duplicate_alias', 'missing_template')
    && array_column($aFilter['findings'], 'check') === array('duplicate_alias', 'missing_template'));
$aOnly = $call($aRead, 'audit_site', array('checks' => array('php_syntax')));
check('audit: a single check runs only that check', array_keys($aOnly['summary']) === array('php_syntax') && count($aOnly['findings']) === 2 && $aOnly['notes'] === array());
$aLimit = $call($aRead, 'audit_site', array('checks' => array('broken_link', 'php_syntax'), 'limit' => 1));
check('audit: count stays real above the limit, details stop', $aLimit['summary']['broken_link']['count'] === 3 && $aLimit['summary']['php_syntax']['count'] === 2
    && count($aLimit['findings']) === 2 && $aLimit['summary']['broken_link']['truncated'] === false
    && count(array_filter($aLimit['notes'], function ($note) { return strpos($note, 'broken_link: 3 found, the first 1 are listed') === 0; })) === 1);
$e = throws('audit: unknown check', ApiException::class, function () use ($call, $aRead) { $call($aRead, 'audit_site', array('checks' => array('nope'))); });
check('audit: unknown check is validation_failed', $e && $e->errorCode === 'validation_failed');
throws('audit: limit above 200', ApiException::class, function () use ($call, $aRead) { $call($aRead, 'audit_site', array('limit' => 201)); });
check('audit: read scope sees the tool in its manifest', in_array('modx_audit_site', array_column(Manifest::tools($aRead), 'name'), true));

// the resource cap: the most recently edited pages are scanned, and the result says so
$cDir = realpath(sys_get_temp_dir()) . '/modxmcp-audit-cap-' . bin2hex(random_bytes(6));
mkdir($cDir . '/core', 0700, true);
$cSite = fakeSite($cDir);
foreach (array(1 => 400, 2 => 300, 3 => 200, 4 => 100) as $id => $edited) {
    $cSite->store('modResource', array('id' => $id, 'pagetitle' => 'Страница ' . $id, 'context_key' => 'web', 'template' => 50, 'published' => 1, 'deleted' => 0, 'uri' => 'c' . $id, 'content' => '', 'editedon' => $edited));
}
$cRead = new Context($cSite, array('scope' => 'read') + $dev->token, $dev->corePath, function () { throw new RuntimeException('no store'); });
$cUncapped = $call($cRead, 'audit_site', array('checks' => array('missing_template')));
SiteAudit::$maxResources = 2;
$cCapped = $call($cRead, 'audit_site', array('checks' => array('missing_template')));
SiteAudit::$maxResources = 5000;
check('audit: below the cap everything is scanned', $cUncapped['summary']['missing_template'] === array('count' => 4, 'truncated' => false, 'scanned' => 4));
check('audit: above the cap the newest-edited pages are scanned and truncated is set with a note', $cCapped['summary']['missing_template'] === array('count' => 2, 'truncated' => true, 'scanned' => 2)
    && array_column($cCapped['findings'], 'id') === array(1, 2) && count(array_filter($cCapped['notes'], function ($note) { return strpos($note, '2 most recently edited of 4 resources') !== false; })) === 1);

// --- Run ---
$uDir = realpath(sys_get_temp_dir()) . '/modxmcp-run-' . bin2hex(random_bytes(6));
mkdir($uDir . '/core/cache/logs', 0700, true);
$uBase = dirname(dirname(__DIR__)) . '/';
$uSite = fakeSite($uDir, array('modxmcp.allow_run' => true, 'base_path' => $uBase));
$uSite->store('modContext', array('key' => 'mgr', 'name' => 'Manager'));
$uSite->store('modContext', array('key' => 'web', 'name' => 'Web'));
$uSite->store('modContext', array('key' => 'second', 'name' => 'Second'));
$uSite->store('modResource', array('id' => 1, 'pagetitle' => 'Главная', 'context_key' => 'web', 'content' => 'x', 'uri' => 'index.html'));
$uSite->store('modResource', array('id' => 2, 'pagetitle' => 'Другая страница', 'context_key' => 'second', 'content' => 'y', 'uri' => 'other.html'));
$uSnippets = array();
$uSnippet = function ($name, callable $body) use ($uSite) {
    static $id = 0;
    $uSite->store('modSnippet', array('id' => ++$id, 'name' => $name, 'snippet' => '', 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => ''));
    $uSite->snippetRunners[$name] = $body;
};
$uChunk = function ($id, $name, $content) use ($uSite) {
    $uSite->store('modChunk', array('id' => $id, 'name' => $name, 'snippet' => $content, 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => ''));
};
$uLog = $uSite->getCachePath() . 'logs/error.log';
file_put_contents($uLog, "[2026-01-01 09:00:00] (ERROR in Old::line @ fake) Старая ошибка\n");
$uSnippet('hello', function (array $scriptProperties, $modx) { return 'Привет, ' . (isset($scriptProperties['name']) ? $scriptProperties['name'] : 'мир'); });
$uSnippet('echoer', function (array $scriptProperties, $modx) { echo 'эхо '; return 'ответ'; });
$uSnippet('where', function (array $scriptProperties, $modx) { return $modx->context->get('key') . '|' . $modx->resourceIdentifier . '|' . ($modx->resource ? $modx->resource->get('pagetitle') : '-'); });
$uSnippet('thrower', function (array $scriptProperties, $modx) { echo 'частично'; throw new RuntimeException('Ошибка в сниппете'); });
$uSnippet('wherethrow', function (array $scriptProperties, $modx) { throw new LogicException($modx->context->get('key')); });
$uSnippet('leaky', function (array $scriptProperties, $modx) { ob_start(); ob_start(); echo 'утечка'; return 'ok'; });
$uSnippet('big', function (array $scriptProperties, $modx) { return str_repeat('я', 100); });
$uSnippet('logger', function (array $scriptProperties, $modx) use ($uLog) { file_put_contents($uLog, "[2026-01-01 10:01:00] (ERROR in Foo::bar @ fake) Ошибка журнала\n[2026-01-01 10:02:00] (WARN @ fake) Предупреждение\n", FILE_APPEND); return 'готово'; });
$uSnippet('structured', function (array $scriptProperties, $modx) { return array('имя' => 'ы', 'n' => 3); });
$uSnippet('tags', function (array $scriptProperties, $modx) { return "строка\nПривет [[\$нет]] и [[+пусто]]"; });
$uSnippet('manytags', function (array $scriptProperties, $modx) { return str_repeat('[[+нет]] ', 25); });
$uChunk(1, 'wrap', '<b>[[+title]]</b> [[*pagetitle]] [[$inner? &t=`вложенный`]]');
$uChunk(2, 'inner', '(внутри [[+t]])');
$uAdmin = new Context($uSite, array('scope' => 'admin') + $dev->token, $dev->corePath, function () { throw new RuntimeException('no store'); });
$uCtx = function ($scope = 'develop', array $token = array()) use ($uSite, $dev) { return new Context($uSite, $token + array('scope' => $scope) + $dev->token, $dev->corePath, function () { throw new RuntimeException('no store'); }); };
$uTools = function ($scope) use ($uCtx) { return array_column(Manifest::tools($uCtx($scope)), 'name'); };
$uCalls = function () use ($uSite) { return count($uSite->runCalls); };
$uHistory = function () use ($call, $uCtx) { return $call($uCtx(), 'history', array('limit' => 100))['changesets']; };
$uState = function () use ($uSite) { return array($uSite->context->get('key'), $uSite->resource, $uSite->resourceIdentifier, ob_get_level()); };
$uBefore = $uState();

// the gate, the scope and the manifest
check('run: with the setting on, a develop token has the tool; a content token does not', in_array('modx_run', $uTools('develop'), true) && !in_array('modx_run', $uTools('content'), true) && !in_array('modx_run', $uTools('read'), true));
$e = throws('run: a content token is refused', ApiException::class, function () use ($call, $uCtx) { $call($uCtx('content'), 'run', array('text' => 'x')); });
check('run: refusal for the scope is forbidden_scope', $e && $e->errorCode === 'forbidden_scope');
$uSite->options['modxmcp.allow_run'] = false;
$e = throws('run: gate off', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('text' => 'x')); });
check('run: gate off is unavailable and the tool is absent from every manifest', $e && $e->errorCode === 'unavailable' && $e->getMessage() === 'disabled_by_setting' && !in_array('modx_run', $uTools('admin'), true) && $uCalls() === 0);
$uSite->options['modxmcp.allow_run'] = true;
$uAction = $uCtx()->actions->get('run');
check('run: effect flags and schema', $uAction->readOnly() === false && $uAction->reversible() === false && $uAction->openWorld() === true && $uAction->destructive() === true && $uAction->scope() === 'develop'
    && $uAction->group() === 'verify' && strpos($uAction->description(), 'NOT journaled') !== false);
check('run: the setting is in the build data and both lexicons', strpos(file_get_contents(dirname(dirname(__DIR__)) . '/_build/data/transport.settings.php'), "'modxmcp.allow_run', 0, 'combo-boolean', 'modxmcp:security'") !== false
    && strpos(file_get_contents($uBase . 'core/components/modxmcp/lexicon/en/setting.inc.php'), "setting_modxmcp.allow_run_desc") !== false
    && strpos(file_get_contents($uBase . 'core/components/modxmcp/lexicon/ru/setting.inc.php'), "setting_modxmcp.allow_run_desc") !== false);

// snippet mode: properties reach the code, the result is a result
$c = $uCtx();
$r = $call($c, 'run', array('snippet' => 'hello', 'properties' => array('name' => 'Мир')));
check('run snippet: properties reach the code', $r['ok'] === true && $r['mode'] === 'snippet' && $r['name'] === 'hello' && $r['output'] === 'Привет, Мир' && $r['output_type'] === 'string'
    && $r['echoed'] === '' && $r['truncated'] === false && $r['bytes'] === strlen('Привет, Мир') && $r['performed'] === true && is_int($r['duration_ms']) && $r['context'] === 'web');
check('run snippet: the warning about untracked changes is given', in_array('Changes made by the executed code are not journaled.', $c->warnings, true));
check('run snippet: no properties is an empty set', $call($uCtx(), 'run', array('snippet' => 'hello'))['output'] === 'Привет, мир');
$r = $call($uCtx(), 'run', array('snippet' => 'echoer'));
check('run snippet: what the snippet echoes and returns are joined, as MODX does, and nothing escapes its buffer', $r['output'] === 'эхо ответ' && $r['echoed'] === '');
$r = $call($uCtx(), 'run', array('snippet' => 'structured'));
check('run snippet: a returned array is JSON and says so', $r['output'] === '{"имя":"ы","n":3}' && $r['output_type'] === 'json');
$r = $call($uCtx(), 'run', array('snippet' => 'leaky'));
check('run snippet: buffers the code left open are closed', $r['ok'] === true && $r['output'] === 'утечкаok' && ob_get_level() === $uBefore[3]);

// chunk mode
$r = $call($uCtx(), 'run', array('chunk' => 'wrap', 'properties' => array('title' => 'Заголовок'), 'resource' => 1));
check('run chunk: placeholders, resource fields and a nested chunk', $r['ok'] === true && $r['mode'] === 'chunk' && $r['name'] === 'wrap' && $r['resource'] === 1
    && $r['output'] === '<b>Заголовок</b> Главная (внутри вложенный)' && $r['unparsed_count'] === 0 && $r['unparsed_tags'] === array());
$r = $call($uCtx(), 'run', array('chunk' => 'wrap'));
check('run chunk: without the resource its tags stay and are listed', $r['output'] === '<b>[[+title]]</b> [[*pagetitle]] (внутри вложенный)' && $r['unparsed_count'] === 2
    && array_column($r['unparsed_tags'], 'tag') === array('[[+title]]', '[[*pagetitle]]') && $r['unparsed_tags'][0]['line'] === 1);

// text mode: the two parser passes of a page, leftovers stay visible
$uSite->parser->passes = array();
$r = $call($uCtx(), 'run', array('text' => "[[*pagetitle]] — [[hello? &name=`Мир`]]\n[[!hello]] [[\$нет]]", 'resource' => 1));
check('run text: cacheable and uncacheable tags are processed, a missing chunk stays', $r['ok'] === true && $r['mode'] === 'text' && !isset($r['name'])
    && $r['output'] === "Главная — Привет, Мир\nПривет, мир [[\$нет]]" && $r['unparsed_count'] === 1 && $r['unparsed_tags'] === array(array('tag' => '[[$нет]]', 'line' => 2)));
check('run text: the cacheable pass, then the uncacheable one, and never the pass that removes unprocessed tags',
    $uSite->parser->passes[0] === array(false, false, 10) && in_array(array(true, false, 10), $uSite->parser->passes, true) && !in_array(true, array_column($uSite->parser->passes, 1), true));
$uSite->parser->passes = array();
$r = $call($uCtx(), 'run', array('text' => "{\$x} без квадратных скобок"));
check('run text: the parser passes also run for a text without [[', $r['ok'] === true && $r['output'] === "{\$x} без квадратных скобок" && $uSite->parser->passes === array(array(false, false, 10), array(true, false, 10)));
$r = $call($uCtx(), 'run', array('snippet' => 'tags'));
check('run: unparsed tags carry their line', $r['unparsed_tags'] === array(array('tag' => '[[$нет]]', 'line' => 2), array('tag' => '[[+пусто]]', 'line' => 2)));
$r = $call($uCtx(), 'run', array('snippet' => 'manytags'));
check('run: at most 20 unparsed tags are listed, the count is real', count($r['unparsed_tags']) === 20 && $r['unparsed_count'] === 25);

// context and resource: set during the run, restored after it
$r = $call($uCtx(), 'run', array('snippet' => 'where', 'context' => 'second', 'resource' => 2));
check('run: the context and the resource are set during the run', $r['output'] === 'second|2|Другая страница' && $r['context'] === 'second' && $r['resource'] === 2);
check('run: they are restored after it', $uState() === $uBefore);
$r = $call($uCtx(), 'run', array('snippet' => 'where'));
check('run: without a resource none is set, the default context is web', $r['output'] === 'web||-' && $uState() === $uBefore);
$uSite->resource = $uSite->getObject('modResource', 1);
$uSite->resourceIdentifier = 1;
$r = $call($uCtx(), 'run', array('snippet' => 'where', 'context' => 'second', 'resource' => 2));
check('run: the previous resource comes back too', $uSite->resourceIdentifier === 1 && (int) $uSite->resource->get('id') === 1);
$uSite->resource = null;
$uSite->resourceIdentifier = null;
$r = $call($uCtx(), 'run', array('snippet' => 'wherethrow', 'context' => 'second', 'resource' => 2));
check('run: a throwing snippet is a result and the state is restored all the same', $r['ok'] === false && $r['error']['message'] === 'second' && $uState() === $uBefore);

// errors of the code under test
$r = $call($uCtx(), 'run', array('snippet' => 'thrower'));
check('run: an exception is a result with type, message, line and a relative file', $r['ok'] === false && $r['error']['type'] === 'RuntimeException' && $r['error']['message'] === 'Ошибка в сниппете'
    && is_int($r['error']['line']) && $r['error']['line'] > 0 && $r['error']['file'] === 'tests/php/run.php' && strpos(json_encode($r), $uBase) === false);
check('run: the partial output is kept', $r['echoed'] === 'частично' && $r['output'] === '' && $uState() === $uBefore);
$e = throws('run: a missing snippet', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('snippet' => 'нет такого')); });
$e2 = throws('run: a missing chunk', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('chunk' => 'нет такого')); });
check('run: missing snippet and chunk are not_found', $e && $e2 && $e->errorCode === 'not_found' && $e2->errorCode === 'not_found');

// truncation: by bytes, never inside a character
$r = $call($uCtx(), 'run', array('snippet' => 'big', 'max_output' => 51));
check('run: output is cut on a character boundary, the real size is reported', $r['truncated'] === true && $r['bytes'] === 200 && strlen($r['output']) === 50 && preg_match('//u', $r['output']) === 1
    && $r['output'] === str_repeat('я', 25));
$r = $call($uCtx(), 'run', array('snippet' => 'big'));
check('run: below the limit nothing is cut', $r['truncated'] === false && $r['bytes'] === 200 && $r['output'] === str_repeat('я', 100));
throws('run: max_output above 200000', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('snippet' => 'big', 'max_output' => 200001)); });

// new error-log lines
$r = $call($uCtx(), 'run', array('snippet' => 'logger'));
check('run: only the log lines written during the run are reported', $r['new_log_errors'] === 2 && count($r['log_lines']) === 2 && $r['log_lines'][0]['message'] === 'Ошибка журнала' && $r['log_lines'][0]['level'] === 'ERROR'
    && $r['log_lines'][1]['message'] === 'Предупреждение');
check('run: a run that logs nothing reports none', $call($uCtx(), 'run', array('snippet' => 'hello'))['new_log_errors'] === 0);

// journal: one informational changeset per run, not reversible, refused by undo
$uHistoryBefore = count($uHistory());
$uRun = $call($uCtx(), 'run', array('snippet' => 'hello', 'properties' => array('name' => 'Мир')));
$uEntries = $uHistory();
check('run: exactly one informational changeset, named after the run, not reversible', count($uEntries) === $uHistoryBefore + 1 && $uRun['changeset_id'] === $uEntries[0]['changeset_id'] && $uRun['reversible'] === false
    && $uEntries[0]['tool'] === 'run' && $uEntries[0]['summary'] === 'run snippet hello' && $uEntries[0]['objects'] === array());
$uText = $call($uCtx(), 'run', array('text' => 'просто текст'));
$uChunkRun = $call($uCtx(), 'run', array('chunk' => 'inner', 'properties' => array('t' => 'x')));
$uEntries = $uHistory();
check('run: chunk and text runs are named too', $uEntries[0]['summary'] === 'run chunk inner' && $uEntries[1]['summary'] === 'run text');
$e = throws('run: modx_undo refuses it', ApiException::class, function () use ($call, $uCtx, $uRun) { $call($uCtx(), 'undo', array('changeset_id' => $uRun['changeset_id'], 'confirm' => true)); });
check('run: the refusal is not_reversible', $e && $e->errorCode === 'not_reversible');
$call($uCtx(), 'run', array('snippet' => 'thrower'));
check('run: a failed run is journaled as failed', $uHistory()[0]['summary'] === 'run snippet thrower (failed)');

// a plan-only token and dry_run do not execute
$uCountBefore = $uCalls();
$uHistoryBefore = count($uHistory());
$uDry = $call($uCtx(), 'run', array('snippet' => 'hello', 'dry_run' => true, 'context' => 'second', 'resource' => 2));
$uPlanned = $call($uCtx('develop', array('plan_only' => true)), 'run', array('chunk' => 'wrap'));
$uPlannedText = $call($uCtx('develop', array('plan_only' => true)), 'run', array('text' => '[[hello]]'));
check('run: dry_run and a plan-only token say what would run and execute nothing', $uCalls() === $uCountBefore && count($uHistory()) === $uHistoryBefore
    && $uDry['dry_run'] === true && $uDry['performed'] === false && $uDry['mode'] === 'snippet' && $uDry['name'] === 'hello' && $uDry['context'] === 'second' && $uDry['resource'] === 2
    && $uPlanned['planned'] === true && $uPlanned['performed'] === false && $uPlanned['would_run'] === 'run chunk wrap in context web' && $uPlannedText['planned'] === true && $uState() === $uBefore);

// validation
foreach (array('none' => array(), 'two' => array('snippet' => 'hello', 'chunk' => 'wrap'), 'three' => array('snippet' => 'hello', 'chunk' => 'wrap', 'text' => 'x')) as $label => $args) {
    $e = throws("run: {$label} of snippet/chunk/text", ApiException::class, function () use ($call, $uCtx, $args) { $call($uCtx(), 'run', $args); });
    check("run: {$label} of snippet/chunk/text is validation_failed", $e && $e->errorCode === 'validation_failed');
}
$e = throws('run: properties with text', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('text' => 'x', 'properties' => array('a' => 1))); });
check('run: properties with text is validation_failed', $e && $e->errorCode === 'validation_failed');
$e = throws('run: a resource of another context', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('snippet' => 'hello', 'resource' => 2)); });
check('run: a resource from another context is validation_failed and nothing ran', $e && $e->errorCode === 'validation_failed' && strpos($e->getMessage(), "'second'") !== false);
$e = throws('run: a missing resource', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('snippet' => 'hello', 'resource' => 99)); });
$e2 = throws('run: an unknown context', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('snippet' => 'hello', 'context' => 'nope')); });
check('run: a missing resource and an unknown context are validation_failed', $e && $e2 && $e->errorCode === 'validation_failed' && $e2->errorCode === 'validation_failed');
throws('run: text longer than 20000 characters', ApiException::class, function () use ($call, $uCtx) { $call($uCtx(), 'run', array('text' => str_repeat('я', 20001))); });
check('run: text of exactly 20000 characters is accepted', $call($uCtx(), 'run', array('text' => str_repeat('я', 20000), 'max_output' => 10))['truncated'] === true);
check('run: none of the failed validations ran anything or left state behind', $uState() === $uBefore);

// --- Tokens page: TokenStore::update, TokenService and the overview of the main page ---
use ModxMCP\Manager\TokenService;
use ModxMCP\Manager\Overview;
$tkCore = dirname(dirname(__DIR__)) . '/core/components/modxmcp/';
$tkDir = realpath(sys_get_temp_dir()) . '/modxmcp-tokens-' . bin2hex(random_bytes(6));
mkdir($tkDir . '/core', 0700, true);
$tkSite = fakeSite($tkDir, array('site_url' => 'https://example.test/', 'assets_url' => '/assets/', 'base_url' => '/'));
$tkSite->store('modUser', array('id' => 1, 'username' => 'admin', 'primary_group' => 0));
$tkSite->store('modUser', array('id' => 2, 'username' => 'Иванов', 'primary_group' => 0));
$tkSite->user = $tkSite->getObject('modUser', 2);
$tkStore = new TokenStore($tkSite);
$tkService = new TokenService($tkSite, $tkSite->user);
$tkRow = function ($id) use ($tkSite) { return $tkSite->pdo->query('SELECT * FROM modx_modxmcp_tokens WHERE id = ' . (int) $id)->fetch(PDO::FETCH_ASSOC); };
$tkThrows = function ($label, callable $fn) {
    try { $fn(); check($label, false); return null; }
    catch (Throwable $e) { check($label, $e instanceof InvalidArgumentException || $e instanceof ApiException); return $e; }
};

// TokenStore::update
$tkA = $tkStore->create('Старый токен', 'develop', false, array(), null, 2);
$tkHash = $tkRow($tkA['id'])['hash'];
$tkGet = $tkStore->get($tkA['id']);
check('tokens page: get returns the public record without hash or token', $tkGet['label'] === 'Старый токен' && !isset($tkGet['hash']) && !isset($tkGet['token']) && $tkStore->get(9999) === null);
$tkU = $tkStore->update($tkA['id'], array('label' => 'Новое имя «тест»'));
check('tokens page: update the label (Cyrillic) and nothing else', $tkU['label'] === 'Новое имя «тест»' && $tkU['scope'] === 'develop' && $tkU['plan_only'] === false && $tkU['denied_groups'] === array());
$tkU = $tkStore->update($tkA['id'], array('plan_only' => true));
check('tokens page: update plan_only', $tkU['plan_only'] === true && $tkU['label'] === 'Новое имя «тест»');
$tkU = $tkStore->update($tkA['id'], array('denied_groups' => array('migx', 'access', 'migx')));
check('tokens page: update denied_groups (duplicates dropped)', $tkU['denied_groups'] === array('migx', 'access'));
$tkAt = time() + 5000;
$tkU = $tkStore->update($tkA['id'], array('expires_at' => $tkAt));
check('tokens page: update expires_at', $tkU['expires_at'] === $tkAt);
$tkU = $tkStore->update($tkA['id'], array('expires_at' => null));
check('tokens page: null clears the expiry', $tkU['expires_at'] === null);
$tkU = $tkStore->update($tkA['id'], array('denied_groups' => array()));
check('tokens page: an empty denied_groups clears them', $tkU['denied_groups'] === array());
$tkU = $tkStore->update($tkA['id'], array('label' => 'Один', 'plan_only' => false, 'denied_groups' => array('lexicon')));
check('tokens page: several fields at once', $tkU['label'] === 'Один' && $tkU['denied_groups'] === array('lexicon'));
$tkThrows('tokens page: scope cannot be changed', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('scope' => 'admin')); });
$tkThrows('tokens page: the hash cannot be changed', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('hash' => str_repeat('a', 64))); });
$tkThrows('tokens page: an unknown key is refused', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('label' => 'x', 'created_by' => 1)); });
$tkThrows('tokens page: an unknown group is refused', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('denied_groups' => array('nope'))); });
$tkThrows('tokens page: a group that is not toggleable is refused', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('denied_groups' => array('resources'))); });
$tkThrows('tokens page: an expiry in the past is refused', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('expires_at' => time() - 10)); });
$tkThrows('tokens page: a non-integer expiry is refused', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('expires_at' => '2030-01-01')); });
$tkThrows('tokens page: a label over 190 characters is refused', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('label' => str_repeat('я', 191))); });
$tkThrows('tokens page: plan_only must be a boolean', function () use ($tkStore, $tkA) { $tkStore->update($tkA['id'], array('plan_only' => 'yes')); });
$tkThrows('tokens page: an unknown token is refused', function () use ($tkStore) { $tkStore->update(9999, array('label' => 'x')); });
$tkU = $tkStore->update($tkA['id'], array('label' => str_repeat('я', 190)));
check('tokens page: a label of exactly 190 characters is accepted', mb_strlen($tkU['label'], 'UTF-8') === 190);
$tkAfter = $tkRow($tkA['id']);
check('tokens page: refused changes left the scope and the hash alone', $tkAfter['scope'] === 'develop' && $tkAfter['hash'] === $tkHash && $tkAfter['denied_groups'] === 'lexicon');
$tkThrows('tokens page: create refuses an unknown group', function () use ($tkStore) { $tkStore->create('x', 'read', false, array('nope')); });
$tkRev = $tkStore->create('Отозванный', 'read', false, array(), null, 2);
$tkStore->revoke($tkRev['id']);
$tkThrows('tokens page: a revoked token cannot be updated', function () use ($tkStore, $tkRev) { $tkStore->update($tkRev['id'], array('label' => 'x')); });
check('tokens page: a revoked token is unchanged after the refusal', $tkRow($tkRev['id'])['label'] === 'Отозванный');

// TokenService::tokens
$tkExp = $tkStore->create('Истёкший', 'content', true, array('migx'), time() + 100, 1);
$tkSite->pdo->exec('UPDATE modx_modxmcp_tokens SET expires_at = ' . (time() - 50) . ' WHERE id = ' . (int) $tkExp['id']);
$tkOld = $tkStore->create('Импортированный', 'admin', false, array(), null, 0);
$tkGone = $tkStore->create('Автор удалён', 'read', false, array(), null, 77);
$tkCtx = Context::forManager($tkSite, $tkSite->user, $tkCore);
$tkMeta = function ($tokenId, $source = 'mcp') { return array('source' => $source, 'token_id' => $tokenId, 'session_id' => null, 'request_id' => null, 'tool' => 'update', 'summary' => 'правка'); };
$tkCtx->journal()->commit($tkMeta($tkA['id']), array());
$tkCtx->journal()->commit($tkMeta($tkA['id']), array());
$tkCtx->journal()->commit($tkMeta($tkExp['id']), array());
$tkCtx->journal()->commit($tkMeta(null, 'manager'), array());
$tkList = $tkService->tokens();
$tkBy = array();
foreach ($tkList as $tk) { $tkBy[$tk['label']] = $tk; }
check('tokens page: tokens are listed newest first, without hashes', array_column($tkList, 'id') === array($tkGone['id'], $tkOld['id'], $tkExp['id'], $tkRev['id'], $tkA['id'])
    && !isset($tkList[0]['hash']) && !isset($tkList[0]['token']));
check('tokens page: status of an active, an expired and a revoked token', $tkBy[str_repeat('я', 190)]['status'] === 'active' && $tkBy['Истёкший']['status'] === 'expired' && $tkBy['Отозванный']['status'] === 'revoked');
check('tokens page: created_by_name is the user name, a dash, or a deleted user', $tkBy[str_repeat('я', 190)]['created_by_name'] === 'Иванов' && $tkBy['Истёкший']['created_by_name'] === 'admin'
    && $tkBy['Импортированный']['created_by_name'] === '—' && $tkBy['Автор удалён']['created_by_name'] === '(deleted user #77)');
check('tokens page: changesets are counted per token, tokens with none have 0, manager changesets are no one\'s',
    $tkBy[str_repeat('я', 190)]['changesets'] === 2 && $tkBy['Истёкший']['changesets'] === 1 && $tkBy['Отозванный']['changesets'] === 0 && $tkBy['Импортированный']['changesets'] === 0);
check('tokens page: the record keeps the rights of the token', $tkBy['Истёкший']['scope'] === 'content' && $tkBy['Истёкший']['plan_only'] === true && $tkBy['Истёкший']['denied_groups'] === array('migx'));

// TokenService::create
$tkFail = function ($label, array $input) use ($tkService) {
    try { $tkService->create($input); check($label, false); }
    catch (ApiException $e) { check($label, $e->errorCode === 'validation_failed'); }
};
$tkFail('tokens page: create needs a label', array('label' => '', 'scope' => 'read'));
$tkFail('tokens page: a blank label is no label', array('label' => " \t ", 'scope' => 'read'));
$tkFail('tokens page: a label over 190 characters is refused by create', array('label' => str_repeat('я', 191), 'scope' => 'read'));
$tkFail('tokens page: create refuses an unknown scope', array('label' => 'x', 'scope' => 'root'));
$tkFail('tokens page: create refuses more than 3650 days', array('label' => 'x', 'scope' => 'read', 'expires_days' => 3651));
$tkFail('tokens page: create refuses negative days', array('label' => 'x', 'scope' => 'read', 'expires_days' => '-1'));
$tkFail('tokens page: create refuses days that are not a number', array('label' => 'x', 'scope' => 'read', 'expires_days' => 'abc'));
$tkFail('tokens page: create refuses an unknown group', array('label' => 'x', 'scope' => 'read', 'denied_groups' => 'migx,nope'));
$tkCount = (int) $tkSite->pdo->query('SELECT COUNT(*) FROM modx_modxmcp_tokens')->fetchColumn();
$tkNew = $tkService->create(array('label' => '  Claude Code на ноутбуке  ', 'scope' => 'develop', 'plan_only' => 'true', 'expires_days' => '30', 'denied_groups' => 'migx,access'));
check('tokens page: create trims the label and stores the choices', $tkNew['label'] === 'Claude Code на ноутбуке' && $tkNew['scope'] === 'develop' && $tkNew['plan_only'] === true
    && $tkNew['denied_groups'] === array('migx', 'access') && abs($tkNew['expires_at'] - (time() + 30 * 86400)) < 5 && $tkNew['created_by'] === 2 && (int) $tkSite->pdo->query('SELECT COUNT(*) FROM modx_modxmcp_tokens')->fetchColumn() === $tkCount + 1);
$tkConfig = json_decode($tkNew['config'], true);
check('tokens page: config is valid JSON with the exact structure and the site URL', $tkConfig === array('mcpServers' => array('modx' => array(
    'command' => 'npx', 'args' => array('-y', 'github:dampilov94/mcp-component'),
    'env' => array('MODX_MCP_SITE_URL' => 'https://example.test/assets/components/modxmcp/api.php', 'MODX_MCP_TOKEN' => $tkNew['token'])))));
check('tokens page: config is pretty-printed with 2 spaces and slashes unescaped', strpos($tkNew['config'], "{\n  \"mcpServers\": {\n    \"modx\": {\n      \"command\": \"npx\"") === 0 && strpos($tkNew['config'], '\\/') === false);
$tkAuth = $tkStore->authenticate($tkConfig['mcpServers']['modx']['env']['MODX_MCP_TOKEN']);
check('tokens page: the token in the config authenticates as the new record', $tkAuth && $tkAuth['id'] === $tkNew['id'] && $tkAuth['label'] === 'Claude Code на ноутбуке');
$tkOff = $tkService->create(array('label' => 'Без срока', 'scope' => 'read', 'plan_only' => 'false'));
check('tokens page: no expiry, and "false" from a checkbox is not true', $tkOff['expires_at'] === null && $tkOff['plan_only'] === false && $tkOff['denied_groups'] === array());
$tkSite->options['site_url'] = 'https://example.test/sub/';
$tkSite->options['assets_url'] = '/sub/assets/';
check('tokens page: a site in a folder keeps the folder in the URL', $tkService->endpoint() === 'https://example.test/sub/assets/components/modxmcp/api.php');
$tkSite->options['assets_url'] = 'https://cdn.example.test/assets/';
check('tokens page: an absolute assets_url is used as it is', $tkService->endpoint() === 'https://cdn.example.test/assets/components/modxmcp/api.php');
$tkSite->options['site_url'] = 'https://example.test/';
$tkSite->options['assets_url'] = '/assets/';
check('tokens page: the endpoint is the one of a standard site', $tkService->endpoint() === 'https://example.test/assets/components/modxmcp/api.php');

// Ready snippets per client for MCP over HTTP (formats from each client's documentation)
$tkConfigs = array_column($tkNew['configs'], null, 'id');
$tkUrl = $tkService->endpoint();
$tkBearer = array('X-MCP-Token' => $tkNew['token']);
check('mcp http: one snippet per client, the bridge last', array_keys($tkConfigs) === array('claude_code', 'codex', 'gemini', 'opencode', 'cursor', 'vscode', 'cline', 'zed', 'node')
    && $tkNew['config'] === $tkConfigs['node']['text']);
$tkJson = function ($id) use ($tkConfigs) { return json_decode($tkConfigs[$id]['text'], true); };
check('mcp http: Claude Code uses type http with the token header', $tkJson('claude_code') === array('mcpServers' => array('modx' => array('type' => 'http', 'url' => $tkUrl, 'headers' => $tkBearer))));
check('mcp http: Gemini CLI uses httpUrl (url would mean SSE)', $tkJson('gemini') === array('mcpServers' => array('modx' => array('httpUrl' => $tkUrl, 'headers' => $tkBearer))));
check('mcp http: opencode is remote, under mcp.servers, with OAuth off', $tkJson('opencode')['mcp']['servers']['modx'] === array('type' => 'remote', 'url' => $tkUrl, 'oauth' => false, 'headers' => $tkBearer));
check('mcp http: Cursor, VS Code, Cline and Zed', $tkJson('cursor') === array('mcpServers' => array('modx' => array('url' => $tkUrl, 'headers' => $tkBearer)))
    && $tkJson('vscode') === array('servers' => array('modx' => array('type' => 'http', 'url' => $tkUrl, 'headers' => $tkBearer)))
    && $tkJson('cline') === array('mcpServers' => array('modx' => array('type' => 'streamableHttp', 'url' => $tkUrl, 'headers' => $tkBearer)))
    && $tkJson('zed') === array('context_servers' => array('modx' => array('url' => $tkUrl, 'headers' => $tkBearer))));
$tkToml = explode("\n", $tkConfigs['codex']['text']);
check('mcp http: Codex CLI reads the token from an environment variable', $tkToml === array('[mcp_servers.modx]', 'url = "' . $tkUrl . '"',
    'env_http_headers = { "X-MCP-Token" = "MODX_MCP_TOKEN" }', '# export MODX_MCP_TOKEN=' . $tkNew['token']));
check('mcp http: every JSON snippet is indented with two spaces', count(array_filter($tkConfigs, function ($c) { return $c['id'] !== 'codex' && strpos($c['text'], "\n  \"") === false; })) === 0);

// TokenService::update
$tkU = $tkService->update($tkNew['id'], array('label' => 'Переименован', 'expires_days' => ''));
check('tokens page: an empty expires_days keeps the expiry', $tkU['label'] === 'Переименован' && $tkU['expires_at'] === $tkNew['expires_at']);
$tkU = $tkService->update($tkNew['id'], array('expires_days' => '0'));
check('tokens page: expires_days 0 removes the expiry', $tkU['expires_at'] === null);
$tkU = $tkService->update($tkNew['id'], array('expires_days' => '90', 'plan_only' => 'false', 'denied_groups' => ''));
check('tokens page: expires_days N sets the expiry, a checkbox "false" and an empty list clear the rest', abs($tkU['expires_at'] - (time() + 90 * 86400)) < 5 && $tkU['plan_only'] === false && $tkU['denied_groups'] === array());
$tkU = $tkService->update($tkNew['id'], array('plan_only' => '1', 'denied_groups' => 'contexts,lexicon'));
check('tokens page: update by CSV of groups', $tkU['plan_only'] === true && $tkU['denied_groups'] === array('contexts', 'lexicon') && $tkU['label'] === 'Переименован');
foreach (array(array('label' => ''), array('expires_days' => '4000'), array('denied_groups' => 'nope')) as $tkBad) {
    try { $tkService->update($tkNew['id'], $tkBad); check('tokens page: update refuses ' . json_encode($tkBad), false); }
    catch (ApiException $e) { check('tokens page: update refuses ' . json_encode($tkBad, JSON_UNESCAPED_UNICODE), $e->errorCode === 'validation_failed'); }
}
check('tokens page: refused updates changed nothing', $tkStore->get($tkNew['id'])['label'] === 'Переименован' && $tkStore->get($tkNew['id'])['denied_groups'] === array('contexts', 'lexicon'));

// revoke
$tkService->revoke($tkOff['id']);
check('tokens page: revoke marks the token revoked and it no longer authenticates', $tkStore->get($tkOff['id'])['revoked_at'] !== null && $tkStore->authenticate($tkNew['token']) !== null
    && array_column(array_filter($tkService->tokens(), function ($t) use ($tkOff) { return $t['id'] === $tkOff['id']; }), 'status') === array('revoked'));
$e = null;
try { $tkService->revoke($tkOff['id']); } catch (ApiException $e) {}
check('tokens page: revoking twice, or an unknown token, is validation_failed', $e && $e->errorCode === 'validation_failed');
$e = null;
try { $tkService->update($tkOff['id'], array('label' => 'x')); } catch (ApiException $e) {}
check('tokens page: a revoked token cannot be updated through the service', $e && $e->errorCode === 'validation_failed');

// no secret in any log
$tkLogged = json_encode(array($tkSite->managerActions, $tkSite->logLines), JSON_UNESCAPED_UNICODE);
$tkSecrets = true;
foreach (array($tkNew, $tkOff) as $tkRec) { $tkSecrets = $tkSecrets && strpos($tkLogged, $tkRec['token']) === false && strpos($tkLogged, TokenStore::hashToken($tkRec['token'])) === false; }
check('tokens page: no token value or hash in the manager actions or the log', $tkSecrets && $tkLogged !== '' );
check('tokens page: manager actions name the token id', $tkSite->managerActions[count($tkSite->managerActions) - 1] === array('action' => 'modxmcp_revoke_token', 'class' => 'modxmcp_token', 'pk' => $tkOff['id'])
    && count(array_filter($tkSite->managerActions, function ($a) { return $a['action'] === 'modxmcp_create_token'; })) === 2
    && count(array_filter($tkSite->managerActions, function ($a) { return $a['action'] === 'modxmcp_update_token'; })) === 4);

$tkLong = str_repeat('я', 190);
$tkLongRecord = $tkService->create(array('label' => $tkLong, 'scope' => 'read'));
check('tokens page: a 190-character Cyrillic label survives creation and authentication', $tkLongRecord['label'] === $tkLong
    && $tkStore->authenticate($tkLongRecord['token'])['label'] === $tkLong);
$tkBoundary = str_repeat('a', 189) . 'я';
$tkBoundaryRecord = $tkStore->create($tkBoundary, 'read');
check('tokens page: creation does not split the last multibyte character', $tkStore->get($tkBoundaryRecord['id'])['label'] === $tkBoundary);
$tkThrows('tokens page: store refuses a long create label just like update', function () use ($tkStore) {
    $tkStore->create(str_repeat('я', 191), 'read');
});

// the overview of the main page
$ovDir = realpath(sys_get_temp_dir()) . '/modxmcp-overview-' . bin2hex(random_bytes(6));
mkdir($ovDir . '/core', 0700, true);
$ovSite = fakeSite($ovDir, array('site_url' => 'https://example.test/', 'assets_url' => '/assets/', 'modxmcp.allow_run' => '1', 'modxmcp.allow_run_processor' => '0',
    'modxmcp.history_track_manager' => 1, 'modxmcp.lint_php' => '0', 'modxmcp.allowed_ips' => ' 10.0.0.1, 10.0.0.2 '));
$ovSite->store('modUser', array('id' => 2, 'username' => 'Иванов', 'primary_group' => 0));
$ovSite->user = $ovSite->getObject('modUser', 2);
$ovOverview = new Overview($ovSite, $ovSite->user);
$ovEmpty = $ovOverview->data();
check('overview: a fresh site has no tokens and no changes, and says so', $ovEmpty['active_tokens'] === 0 && $ovEmpty['recent'] === array() && $ovEmpty['counts_24h'] === array('mcp' => 0, 'manager' => 0, 'external' => 0));
$ovDanger = array();
foreach ($ovEmpty['dangerous'] as $d) { $ovDanger[$d['key']] = $d; }
check('overview: the dangerous settings come in a fixed order', array_keys($ovDanger) === array('modxmcp.allow_run', 'modxmcp.allow_run_processor', 'modxmcp.allow_query_db', 'modxmcp.history_track_manager', 'modxmcp.lint_php', 'modxmcp.require_https', 'modxmcp.allowed_ips'));
check('overview: on, off and a setting that does not exist', $ovDanger['modxmcp.allow_run']['on'] === true && $ovDanger['modxmcp.allow_run']['exists'] === true && $ovDanger['modxmcp.allow_run_processor']['on'] === false
    && $ovDanger['modxmcp.history_track_manager']['on'] === true && $ovDanger['modxmcp.lint_php']['on'] === false
    && $ovDanger['modxmcp.allow_query_db']['exists'] === false && $ovDanger['modxmcp.allow_query_db']['on'] === false && $ovDanger['modxmcp.require_https']['exists'] === false);
check('overview: allowed_ips shows the list trimmed, a missing one is empty and does not exist', $ovDanger['modxmcp.allowed_ips']['value'] === '10.0.0.1, 10.0.0.2' && $ovDanger['modxmcp.allowed_ips']['type'] === 'text');
$ovSite->options['modxmcp.allowed_ips'] = '';
check('overview: an empty allowed_ips exists and means any address', array_column($ovOverview->dangerous(), null, 'key')['modxmcp.allowed_ips']['value'] === '' && array_column($ovOverview->dangerous(), null, 'key')['modxmcp.allowed_ips']['exists'] === true);
$ovStore = new TokenStore($ovSite);
$ovOne = $ovStore->create('Рабочий', 'develop');
$ovTwo = $ovStore->create('Второй', 'read');
$ovStore->create('Короткий', 'read', false, array(), time() + 100);
$ovStore->revoke($ovTwo['id']);
$ovJournal = Context::forManager($ovSite, $ovSite->user, $tkCore)->journal();
$ovIds = array();
foreach (array(array('mcp', 'первое'), array('mcp', 'второе'), array('manager', 'третье'), array('external', 'четвёртое'), array('mcp', 'пятое'), array('mcp', 'шестое'), array('manager', 'седьмое')) as $i => $ovC) {
    $ovIds[] = $ovJournal->commit(array('source' => $ovC[0], 'token_id' => $ovC[0] === 'mcp' ? $ovOne['id'] : null, 'user_id' => $ovC[0] === 'manager' ? 2 : null, 'session_id' => null, 'request_id' => null, 'tool' => 'update', 'summary' => $ovC[1]), array());
}
$ovSite->pdo->exec('UPDATE modx_modxmcp_changesets SET created_at = ' . (time() - 90000) . ' WHERE id IN (' . $ovIds[0] . ',' . $ovIds[3] . ')');
$ovData = $ovOverview->data();
check('overview: five newest changesets with their authors and summaries', array_column($ovData['recent'], 'summary') === array('седьмое', 'шестое', 'пятое', 'четвёртое', 'третье')
    && $ovData['recent'][0]['author'] === 'Иванов' && $ovData['recent'][1]['author'] === 'Рабочий' && $ovData['recent'][0]['source'] === 'manager' && $ovData['recent'][3]['source'] === 'external');
check('overview: counts of the last 24 hours by source leave out older changesets', $ovData['counts_24h'] === array('mcp' => 3, 'manager' => 2, 'external' => 0));
check('overview: active tokens leave out revoked ones, the rest of the status', $ovData['active_tokens'] === 2 && $ovData['enabled'] === true && $ovData['version'] === Kernel::VERSION
    && $ovData['endpoint'] === 'https://example.test/assets/components/modxmcp/api.php' && $ovData['auto_static'] === true);
check('overview: the result is plain JSON data without secrets', strpos(json_encode($ovData), 'mcp_') === false && json_decode(json_encode($ovData), true) === $ovData);

// --- Drafts ---
use ModxMCP\Draft\DraftStore;
use ModxMCP\Manager\DraftService;
$dCore = dirname(dirname(__DIR__)) . '/core/components/modxmcp/';
$dDir = realpath(sys_get_temp_dir()) . '/modxmcp-drafts-' . bin2hex(random_bytes(6));
mkdir($dDir . '/core', 0700, true);
$dSite = fakeSite($dDir, array('site_url' => 'https://example.test/', 'manager_url' => '/manager/'));
$dSite->options['modxmcp.auto_static'] = false;
$dSite->store('modUser', array('id' => 2, 'username' => 'Иванов', 'primary_group' => 0));
$dSite->store('modUser', array('id' => 602, 'username' => 'Редактор', 'primary_group' => 0));
$dSite->user = $dSite->getObject('modUser', 2);
$dTokens = new TokenStore($dSite);
$dTokenRec = $dTokens->create('Рабочий', 'develop');
unset($dTokenRec['token']);
$dActor = function (array $override = array()) use ($dSite, $dCore, $dTokenRec) {
    $c = new Context($dSite, $override + $dTokenRec, $dCore, function () { throw new RuntimeException('no store in tests'); });
    $c->sessionId = 'session-drafts-0001';
    return $c;
};
$dDev = $dActor();
$dInvoke = function (Context $c, $op, $id, array $args = array(), array $more = array()) use ($call) {
    $params = array('kind' => 'resource', 'op' => $op) + ($id === null ? array() : array('id' => $id)) + ($args ? array('args' => $args) : array()) + $more;
    return $call($c, 'invoke', $params);
};
$dSite->store('modTemplate', array('id' => 2, 'templatename' => 'Страница', 'content' => '', 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => '', 'icon' => ''));
$dSite->store('modTemplate', array('id' => 3, 'templatename' => 'Лендинг', 'content' => '', 'category' => 0, 'static' => 0, 'static_file' => '', 'source' => 0, 'locked' => 0, 'description' => '', 'icon' => ''));
$dSite->store('modTemplateVar', array('id' => 20, 'name' => 'subtitle', 'default_text' => 'по умолчанию', 'caption' => '', 'type' => 'text', 'category' => 0));
$dSite->store('modTemplateVar', array('id' => 21, 'name' => 'seo', 'default_text' => '', 'caption' => '', 'type' => 'text', 'category' => 0));
foreach (array(array(20, 2), array(21, 2), array(20, 3)) as $dLink) { $dSite->store('modTemplateVarTemplate', array('tmplvarid' => $dLink[0], 'templateid' => $dLink[1], 'rank' => 0)); }
$dTv = function ($id) use ($dSite) {
    $out = array();
    foreach ($dSite->getCollection('modTemplateVarResource', array('contentid' => $id)) as $row) { $out[(int) $row->get('tmplvarid')] = (string) $row->get('value'); }
    ksort($out);
    return $out;
};
$dCount = function ($table, $where = '1=1', array $params = array()) use ($dSite) {
    $st = $dSite->pdo->prepare('SELECT COUNT(*) FROM modx_modxmcp_' . $table . ' WHERE ' . $where);
    $st->execute($params);
    return (int) $st->fetchColumn();
};
$dChangesIn = function ($changeset) use ($dCount) { return $dCount('changes', 'changeset_id = ?', array($changeset)); };
$dLast = function () use ($dSite) { $row = $dSite->pdo->query('SELECT * FROM modx_modxmcp_changesets ORDER BY id DESC LIMIT 1')->fetch(PDO::FETCH_ASSOC); $row['id'] = (int) $row['id']; return $row; };
$dGet = function ($id) use ($call, $dDev) { return $call($dDev, 'get', array('kind' => 'resource', 'id' => $id)); };

$dSection = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Раздел')));
$dA = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Главная страница', 'alias' => 'glavnaya', 'parent' => $dSection['id'], 'template' => 2,
    'content' => "<h1>Заголовок</h1>\n<p>Старый текст</p>", 'published' => true, 'longtitle' => 'Длинный', 'menuindex' => 3),
    'relations' => array('tvs' => array('subtitle' => 'Подзаголовок', 'seo' => 'ключевые слова'))));
$dABefore = $dGet($dA['id']);
$dTrashBefore = $dSite->getCount('modResource', array('deleted' => 1));

// create_draft
$dCreate = $dInvoke($dDev, 'create_draft', $dA['id']);
$dDraft = $dCreate['draft_id'];
$dDraftRow = $dSite->row('modResource', $dDraft);
check('drafts: create_draft returns the draft, a preview address, the note and the base revision', is_int($dDraft) && $dDraft !== $dA['id'] && $dCreate['op'] === 'create_draft'
    && $dCreate['preview_url'] === 'https://example.test/glavnaya-draft-' . $dDraft && strpos($dCreate['preview_note'], 'logged in to the manager') !== false && $dCreate['base_revision'] === $dABefore['revision']);
check('drafts: the copy is unpublished, hidden, not searchable, unscheduled and has the draft alias', $dDraftRow['published'] === '0' && $dDraftRow['hidemenu'] === '1' && $dDraftRow['searchable'] === '0'
    && (int) $dDraftRow['pub_date'] === 0 && (int) $dDraftRow['unpub_date'] === 0 && $dDraftRow['alias'] === 'glavnaya-draft-' . $dDraft && $dDraftRow['isfolder'] === '0');
check('drafts: title, parent, template, content, class and the other fields are the original\'s', $dDraftRow['pagetitle'] === 'Главная страница' && (int) $dDraftRow['parent'] === $dSection['id']
    && (int) $dDraftRow['template'] === 2 && $dDraftRow['content'] === "<h1>Заголовок</h1>\n<p>Старый текст</p>" && $dDraftRow['class_key'] === 'modDocument' && $dDraftRow['longtitle'] === 'Длинный' && (int) $dDraftRow['menuindex'] === 3);
check('drafts: TV values are copied', $dTv($dDraft) === array(20 => 'Подзаголовок', 21 => 'ключевые слова'));
check('drafts: one changeset with the draft only, the original untouched', $dChangesIn($dCreate['changeset_id']) === 1 && $dLast()['summary'] === "create draft {$dDraft} of resource {$dA['id']}"
    && $dGet($dA['id'])['revision'] === $dABefore['revision']);
$dLinks = $dSite->pdo->query('SELECT * FROM modx_modxmcp_drafts')->fetchAll(PDO::FETCH_ASSOC);
check('drafts: the link row has the original, the draft, the token and the base revision', count($dLinks) === 1 && (int) $dLinks[0]['original_id'] === $dA['id'] && (int) $dLinks[0]['draft_id'] === $dDraft
    && (int) $dLinks[0]['token_id'] === (int) $dTokenRec['id'] && $dLinks[0]['user_id'] === null && $dLinks[0]['base_revision'] === $dABefore['revision']);

// refusals
$e = throws('drafts: a second draft of the same page is refused', ApiException::class, function () use ($dInvoke, $dDev, $dA) { $dInvoke($dDev, 'create_draft', $dA['id']); });
check('drafts: the refusal names the open draft', $e && $e->errorCode === 'validation_failed' && strpos($e->getMessage(), (string) $dDraft) !== false);
$e = throws('drafts: a draft of a draft is refused', ApiException::class, function () use ($dInvoke, $dDev, $dDraft) { $dInvoke($dDev, 'create_draft', $dDraft); });
check('drafts: a draft of a draft is validation_failed', $e && $e->errorCode === 'validation_failed' && strpos($e->getMessage(), 'itself a draft') !== false);
$dLinkPage = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Ссылка', 'class_key' => 'modWebLink')));
$e = throws('drafts: a page of another class is refused', ApiException::class, function () use ($dInvoke, $dDev, $dLinkPage) { $dInvoke($dDev, 'create_draft', $dLinkPage['id']); });
check('drafts: the refusal names the class', $e && $e->errorCode === 'validation_failed' && strpos($e->getMessage(), 'modWebLink') !== false && $dCount('drafts') === 1);
$dGone = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Удалённая')));
$call($dDev, 'delete', array('kind' => 'resource', 'id' => $dGone['id']));
$e = throws('drafts: a page in the trash is refused', ApiException::class, function () use ($dInvoke, $dDev, $dGone) { $dInvoke($dDev, 'create_draft', $dGone['id']); });
check('drafts: a deleted original is validation_failed', $e && $e->errorCode === 'validation_failed' && strpos($e->getMessage(), 'trash') !== false);
$e = throws('drafts: a read token cannot make a draft', ApiException::class, function () use ($dInvoke, $dActor, $dA) { $dInvoke($dActor(array('scope' => 'read')), 'create_draft', $dA['id']); });
check('drafts: the read scope is forbidden_scope', $e && $e->errorCode === 'forbidden_scope');
$dPlanOnly = $dInvoke($dActor(array('plan_only' => true)), 'create_draft', $dA['id']);
check('drafts: a plan-only token only validates', !empty($dPlanOnly['dry_run']) && $dCount('drafts') === 1);

// an original without an alias
$dSite->store('modResource', array('id' => 900, 'pagetitle' => 'Без алиаса', 'alias' => '', 'uri' => '', 'context_key' => 'web', 'parent' => 0, 'template' => 0, 'content' => 'x', 'published' => 1, 'deleted' => 0,
    'class_key' => 'modDocument', 'isfolder' => 0, 'hidemenu' => 0, 'searchable' => 1, 'richtext' => 1, 'cacheable' => 1, 'uri_override' => 0, 'menuindex' => 0, 'editedon' => 1));
$dNoAlias = $dInvoke($dDev, 'create_draft', 900);
check('drafts: an original without an alias gets draft-<id>', $dSite->row('modResource', $dNoAlias['draft_id'])['alias'] === 'draft-' . $dNoAlias['draft_id']);
$dInvoke($dDev, 'discard_draft', 900, array('confirm' => true));

// editing the draft: the live page is not touched
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dDraft, 'fields' => array('pagetitle' => 'Новая главная', 'longtitle' => 'Новый длинный', 'description' => 'Описание', 'introtext' => 'Кратко',
    'menutitle' => 'Меню', 'link_attributes' => 'rel="x"', 'richtext' => false, 'menuindex' => 7, 'alias' => 'drugoy-alias', 'published' => true, 'searchable' => true), 'relations' => array('tvs' => array('subtitle' => 'Новый подзаголовок', 'seo' => ''))));
$call($dDev, 'edit_code', array('kind' => 'resource', 'id' => $dDraft, 'edits' => array(array('start_line' => 2, 'replacement' => '<p>Новый текст</p>', 'expect' => '<p>Старый текст</p>'))));
check('drafts: the draft can be edited with update, edit_code and its TVs', $dSite->row('modResource', $dDraft)['content'] === "<h1>Заголовок</h1>\n<p>Новый текст</p>" && $dTv($dDraft) === array(20 => 'Новый подзаголовок')
    && $dGet($dA['id'])['revision'] === $dABefore['revision']);

// the plan
$dPlan = $dInvoke($dDev, 'apply_draft', $dA['id']);
check('drafts: without confirm apply_draft only plans', !empty($dPlan['dry_run']) && $dPlan['performed'] === false && $dGet($dA['id'])['revision'] === $dABefore['revision'] && $dSite->row('modResource', $dDraft) !== null);
check('drafts: the plan lists the changed fields with old and new values', $dPlan['changes']['pagetitle'] === array('old' => 'Главная страница', 'new' => 'Новая главная')
    && $dPlan['changes']['richtext'] === array('old' => true, 'new' => false) && $dPlan['changes']['longtitle']['new'] === 'Новый длинный' && !isset($dPlan['changes']['template']) && !isset($dPlan['changes']['alias']));
check('drafts: the plan shows content as a line diff', strpos($dPlan['changes']['content']['diff'], "-<p>Старый текст</p>\n+<p>Новый текст</p>") !== false);
check('drafts: the plan lists the TV changes, a cleared TV is the default', $dPlan['tvs'] == array('seo' => array('old' => 'ключевые слова', 'new' => ''), 'subtitle' => array('old' => 'Подзаголовок', 'new' => 'Новый подзаголовок'))
    && $dPlan['original_changed'] === false && $dPlan['original_changed_fields'] === array() && $dPlan['original_id'] === $dA['id'] && $dPlan['draft_id'] === $dDraft);
$dPlanDraft = $dInvoke($dDev, 'apply_draft', $dDraft);
check('drafts: the plan is the same when asked on the draft', $dPlanDraft['changes'] == $dPlan['changes'] && $dPlanDraft['tvs'] == $dPlan['tvs'] && $dPlanDraft['original_id'] === $dA['id']);
$dPlanDry = $dInvoke($dDev, 'apply_draft', $dA['id'], array('confirm' => true), array('dry_run' => true));
check('drafts: dry_run never confirms', $dPlanDry['performed'] === false && $dSite->row('modResource', $dDraft) !== null);
$dPlanOnlyApply = $dInvoke($dActor(array('plan_only' => true)), 'apply_draft', $dA['id'], array('confirm' => true));
check('drafts: a plan-only token never confirms', $dPlanOnlyApply['performed'] === false && $dSite->row('modResource', $dDraft) !== null);

// the audit ignores a draft: an address shared with the original and a broken link in its content
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dDraft, 'fields' => array('uri_override' => true, 'uri' => 'glavnaya', 'content' => "<h1>Заголовок</h1>\n<p>Новый текст [[~9999]]</p>")));
$dAudit = $call($dActor(array('scope' => 'read')), 'audit_site', array('checks' => array('broken_link', 'duplicate_alias', 'missing_template')));
check('drafts: the audit does not report a draft\'s address or links', !array_filter($dAudit['findings'], function ($f) use ($dDraft) { return $f['id'] === $dDraft || (isset($f['details']['ids']) && in_array($dDraft, $f['details']['ids'], true)); }));
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dA['id'], 'fields' => array('uri_override' => true, 'uri' => 'glavnaya', 'content' => "<h1>Заголовок</h1>\n<p>Старый текст [[~9999]]</p>")));
$dAudit = $call($dActor(array('scope' => 'read')), 'audit_site', array('checks' => array('broken_link')));
check('drafts: the same link on a normal page is reported', count(array_filter($dAudit['findings'], function ($f) use ($dA) { return $f['id'] === $dA['id']; })) === 1);
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dA['id'], 'fields' => array('uri_override' => false, 'content' => "<h1>Заголовок</h1>\n<p>Старый текст</p>")));
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dDraft, 'fields' => array('uri_override' => false, 'content' => "<h1>Заголовок</h1>\n<p>Новый текст</p>")));
$dABase = $dGet($dA['id']);
$dLinkNow = $dSite->pdo->query('SELECT base_revision FROM modx_modxmcp_drafts')->fetchColumn();
check('drafts: restoring the original\'s text gives its first revision back', $dABase['revision'] === $dLinkNow);

// markers
$dGetA = $dGet($dA['id']);
$dGetD = $dGet($dDraft);
check('drafts: get shows draft_id on the page and draft_of on the draft', $dGetA['draft_id'] === $dDraft && !isset($dGetA['draft_of']) && $dGetD['draft_of'] === $dA['id'] && !isset($dGetD['draft_id']));
check('drafts: a page without a draft has no marker', !isset($dGet($dSection['id'])['draft_id']) && !isset($dGet($dSection['id'])['draft_of']));
$dList = array_column($call($dDev, 'list', array('kind' => 'resource', 'limit' => 100))['items'], null, 'id');
check('drafts: list shows the markers', $dList[$dA['id']]['draft_id'] === $dDraft && $dList[$dDraft]['draft_of'] === $dA['id'] && !isset($dList[$dSection['id']]['draft_id']));
$dTree = $call($dDev, 'resource_tree', array('depth' => 3));
$dNodes = array();
$dWalk = function (array $nodes) use (&$dWalk, &$dNodes) { foreach ($nodes as $n) { $dNodes[$n['id']] = $n; if (isset($n['nodes'])) { $dWalk($n['nodes']); } } };
$dWalk($dTree['nodes']);
check('drafts: the tree marks the page and the draft', $dNodes[$dA['id']]['draft_id'] === $dDraft && $dNodes[$dDraft]['draft_of'] === $dA['id'] && !isset($dNodes[$dSection['id']]['draft_id']));
$dListing = $dInvoke($dActor(array('scope' => 'read')), 'list_drafts', null);
check('drafts: list_drafts lists the open draft', count($dListing['drafts']) === 1 && $dListing['drafts'][0]['original_id'] === $dA['id'] && $dListing['drafts'][0]['original_title'] === 'Главная страница'
    && $dListing['drafts'][0]['draft_id'] === $dDraft && $dListing['drafts'][0]['author'] === 'Рабочий' && $dListing['drafts'][0]['original_changed'] === false
    && $dListing['drafts'][0]['preview_url'] === 'https://example.test/drugoy-alias' && is_int($dListing['drafts'][0]['created_at']));
$e = throws('drafts: list_drafts takes no id', ApiException::class, function () use ($dInvoke, $dDev, $dA) { $dInvoke($dDev, 'list_drafts', $dA['id']); });

// deleting and children
$dBlocked = function (callable $fn, $label) {
    $e = throws($label, ApiException::class, $fn);
    return $e && $e->errorCode === 'validation_failed';
};
$dDeleteOriginal = $dBlocked(function () use ($call, $dDev, $dA) { $call($dDev, 'delete', array('kind' => 'resource', 'id' => $dA['id'])); }, 'drafts: deleting a page with a draft is refused');
$dDeleteDraft = $dBlocked(function () use ($call, $dDev, $dDraft) { $call($dDev, 'delete', array('kind' => 'resource', 'id' => $dDraft)); }, 'drafts: deleting a draft is refused');
check('drafts: both delete refusals are validation_failed and nothing was deleted', $dDeleteOriginal && $dDeleteDraft && $dSite->getCount('modResource', array('deleted' => 1)) === $dTrashBefore + 1);
$dBulkDelete = $dBlocked(function () use ($call, $dDev, $dA, $dSection) { $call($dDev, 'bulk_resources', array('operation' => 'delete', 'ids' => array($dSection['id'], $dA['id']))); }, 'drafts: a bulk delete of a page with a draft is refused');
$dBulkDraft = $dBlocked(function () use ($call, $dDev, $dDraft) { $call($dDev, 'bulk_resources', array('operation' => 'delete', 'ids' => array($dDraft))); }, 'drafts: a bulk delete of a draft is refused');
check('drafts: bulk delete refusals change nothing', $dBulkDelete && $dBulkDraft && (int) $dSite->row('modResource', $dSection['id'])['deleted'] === 0 && $dSite->row('modResource', $dA['id'])['deleted'] === '0');
$dChildCreate = $dBlocked(function () use ($call, $dDev, $dDraft) { $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Ребёнок', 'parent' => $dDraft))); }, 'drafts: a page under a draft is refused on create');
$dChildUpdate = $dBlocked(function () use ($call, $dDev, $dDraft, $dSection) { $call($dDev, 'update', array('kind' => 'resource', 'id' => $dSection['id'], 'fields' => array('parent' => $dDraft))); }, 'drafts: a page under a draft is refused on update');
$dChildMove = $dBlocked(function () use ($call, $dDev, $dDraft, $dSection) { $call($dDev, 'bulk_resources', array('operation' => 'move', 'ids' => array($dSection['id']), 'parent' => $dDraft)); }, 'drafts: a page under a draft is refused on bulk move');
check('drafts: nothing was put under a draft', $dChildCreate && $dChildUpdate && $dChildMove && $dSite->getCount('modResource', array('parent' => $dDraft)) === 0);

// apply, asked on the draft
$dJournalBefore = $dCount('changesets');
$dApply = $dInvoke($dDev, 'apply_draft', $dDraft, array('confirm' => true));
$dOrig = $dSite->row('modResource', $dA['id']);
check('drafts: apply copies exactly the listed fields', $dApply['applied'] === true && $dApply['original_id'] === $dA['id'] && $dOrig['pagetitle'] === 'Новая главная' && $dOrig['longtitle'] === 'Новый длинный'
    && $dOrig['description'] === 'Описание' && $dOrig['introtext'] === 'Кратко' && $dOrig['menutitle'] === 'Меню' && $dOrig['link_attributes'] === 'rel="x"' && $dOrig['richtext'] === '0'
    && $dOrig['content'] === "<h1>Заголовок</h1>\n<p>Новый текст</p>" && (int) $dOrig['template'] === 2);
check('drafts: alias, parent, published, menu, search flags and the schedule of the original stay', $dOrig['alias'] === 'glavnaya' && (int) $dOrig['parent'] === $dSection['id'] && $dOrig['published'] === '1'
    && $dOrig['hidemenu'] === '0' && $dOrig['searchable'] === '1' && (int) $dOrig['menuindex'] === 3 && (int) $dOrig['pub_date'] === 0 && $dOrig['class_key'] === 'modDocument');
check('drafts: TV values are copied and a TV the draft has no value for is cleared', $dTv($dA['id']) === array(20 => 'Новый подзаголовок'));
check('drafts: the draft is gone completely, with nothing in the trash and no link', $dSite->row('modResource', $dDraft) === null && $dTv($dDraft) === array()
    && $dSite->getCount('modResource', array('deleted' => 1)) === $dTrashBefore + 1 && $dCount('drafts') === 0
);
check('drafts: one changeset for all of it, named by the draft and the page', $dCount('changesets') === $dJournalBefore + 1 && $dLast()['summary'] === "apply draft {$dDraft} to resource {$dA['id']}"
    && $dChangesIn($dApply['changeset_id']) === 2 && $dLast()['source'] === 'mcp');
check('drafts: the page has no draft marker any more', !isset($dGet($dA['id'])['draft_id']) && $call($dDev, 'resource_tree', array('depth' => 3))['nodes'][0]['nodes'][0]['pagetitle'] === 'Новая главная');
check('drafts: the link was archived under the changeset that removed the draft', $dCount('draft_archive', 'changeset_id = ? AND draft_id = ?', array($dApply['changeset_id'], $dDraft)) === 1);

// undo of the apply
$dNewRev = $dGet($dA['id'])['revision'];
$call($dDev, 'undo', array('changeset_id' => $dApply['changeset_id'], 'confirm' => true));
$dOrig = $dSite->row('modResource', $dA['id']);
check('drafts: undo restores the old page and its TVs', $dOrig['pagetitle'] === 'Главная страница' && $dOrig['content'] === "<h1>Заголовок</h1>\n<p>Старый текст</p>" && $dOrig['richtext'] === '1'
    && $dTv($dA['id']) === array(20 => 'Подзаголовок', 21 => 'ключевые слова') && $dGet($dA['id'])['revision'] === $dABase['revision']);
check('drafts: undo brings the draft back with its edits and TVs', $dSite->row('modResource', $dDraft)['pagetitle'] === 'Новая главная' && $dSite->row('modResource', $dDraft)['alias'] === 'drugoy-alias'
    && $dTv($dDraft) === array(20 => 'Новый подзаголовок'));
check('drafts: undo gives the link back from the archive', $dCount('drafts', 'draft_id = ? AND original_id = ?', array($dDraft, $dA['id'])) === 1 && $dCount('draft_archive', 'draft_id = ?', array($dDraft)) === 0
    && $dGet($dA['id'])['draft_id'] === $dDraft && $dInvoke($dDev, 'list_drafts', null)['drafts'][0]['original_changed'] === false);
$dUndoId = $dLast()['id'];
$call($dDev, 'undo', array('changeset_id' => $dUndoId, 'confirm' => true));
check('drafts: undoing the undo applies again and takes the link away again', $dSite->row('modResource', $dA['id'])['pagetitle'] === 'Новая главная' && $dSite->row('modResource', $dDraft) === null
    && $dCount('drafts') === 0 && $dCount('draft_archive', 'draft_id = ?', array($dDraft)) === 1);
$call($dDev, 'undo', array('changeset_id' => $dLast()['id'], 'confirm' => true));
check('drafts: and once more back', $dSite->row('modResource', $dDraft) !== null && $dCount('drafts') === 1 && $dCount('draft_archive', 'draft_id = ?', array($dDraft)) === 0);

// discard, undo
$dBeforeDiscard = $dGet($dA['id'])['revision'];
$dDiscardPlan = $dInvoke($dDev, 'discard_draft', $dA['id']);
check('drafts: discard_draft without confirm plans', !empty($dDiscardPlan['dry_run']) && $dDiscardPlan['performed'] === false && $dDiscardPlan['would_remove']['pagetitle'] === 'Новая главная'
    && $dSite->row('modResource', $dDraft) !== null);
$dDiscard = $dInvoke($dDev, 'discard_draft', $dA['id'], array('confirm' => true));
check('drafts: discard removes the draft and the link in one changeset, the page is untouched', $dDiscard['discarded'] === true && $dSite->row('modResource', $dDraft) === null && $dCount('drafts') === 0
    && $dChangesIn($dDiscard['changeset_id']) === 1 && $dLast()['summary'] === "discard draft {$dDraft} of resource {$dA['id']}" && $dGet($dA['id'])['revision'] === $dBeforeDiscard
    && $dSite->getCount('modResource', array('deleted' => 1)) === $dTrashBefore + 1);
$call($dDev, 'undo', array('changeset_id' => $dDiscard['changeset_id'], 'confirm' => true));
check('drafts: undo of a discard brings the draft and its link back', $dSite->row('modResource', $dDraft)['pagetitle'] === 'Новая главная' && $dTv($dDraft) === array(20 => 'Новый подзаголовок')
    && $dCount('drafts', 'draft_id = ?', array($dDraft)) === 1 && $dCount('draft_archive', 'draft_id = ?', array($dDraft)) === 0);
$e = throws('drafts: discard on a page without a draft', ApiException::class, function () use ($dInvoke, $dDev, $dSection) { $dInvoke($dDev, 'discard_draft', $dSection['id'], array('confirm' => true)); });
check('drafts: it is validation_failed', $e && $e->errorCode === 'validation_failed');
$dInvoke($dDev, 'discard_draft', $dDraft, array('confirm' => true));
check('drafts: discard works on the draft itself', $dSite->row('modResource', $dDraft) === null && $dCount('drafts') === 0);
$call($dDev, 'undo', array('changeset_id' => $dLast()['id'], 'confirm' => true));
// an undo of the creation removes the draft and the link
$dCreate2 = $dInvoke($dDev, 'create_draft', $dSection['id']);
$call($dDev, 'undo', array('changeset_id' => $dCreate2['changeset_id'], 'confirm' => true));
check('drafts: undo of create_draft removes the draft and its link', $dSite->row('modResource', $dCreate2['draft_id']) === null && $dCount('drafts', 'draft_id = ?', array($dCreate2['draft_id'])) === 0);
$call($dDev, 'undo', array('changeset_id' => $dLast()['id'], 'confirm' => true));
check('drafts: and undoing that undo brings both back', $dSite->row('modResource', $dCreate2['draft_id']) !== null && $dCount('drafts', 'draft_id = ?', array($dCreate2['draft_id'])) === 1);
$dInvoke($dDev, 'discard_draft', $dSection['id'], array('confirm' => true));

// conflicts: the page changed after the draft was made
$dConflictBefore = $dGet($dA['id']);
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dA['id'], 'fields' => array('introtext' => 'Правка живой страницы', 'description' => 'Живое описание')));
$dPlan2 = $dInvoke($dDev, 'apply_draft', $dA['id']);
check('drafts: the plan says the original changed, with the fields', $dPlan2['original_changed'] === true && $dPlan2['original_changed_fields'] === array('description', 'introtext') && strpos($dPlan2['warning'], 'force') !== false);
$dBeforeConflict = $dSite->tableDump('modResource');
$e = throws('drafts: apply over a changed page is refused', ApiException::class, function () use ($dInvoke, $dDev, $dDraft) { $dInvoke($dDev, 'apply_draft', $dDraft, array('confirm' => true)); });
check('drafts: the refusal is revision_conflict naming the changes, and nothing changed', $e && $e->errorCode === 'revision_conflict' && $e->details['changed'] === array('description', 'introtext')
    && $dSite->tableDump('modResource') === $dBeforeConflict && $dSite->row('modResource', $dDraft) !== null);
$dContext = $dActor();
$dForced = $dInvoke($dContext, 'apply_draft', $dA['id'], array('confirm' => true), array('force' => true));
check('drafts: force applies anyway with a warning', $dForced['applied'] === true && $dSite->row('modResource', $dA['id'])['introtext'] === 'Кратко' && $dSite->row('modResource', $dDraft) === null
    && count(array_filter($dContext->warnings, function ($w) { return strpos($w, 'changed after the draft') !== false; })) === 1);
$call($dDev, 'undo', array('changeset_id' => $dForced['changeset_id'], 'confirm' => true));

// open in the manager
$dSite->lockResource($dA['id'], 602);
$e = throws('drafts: applying to a page open in the manager is refused', ApiException::class, function () use ($dInvoke, $dDev, $dA) { $dInvoke($dDev, 'apply_draft', $dA['id'], array('confirm' => true), array('force' => false)); });
check('drafts: it is locked, naming the person', $e && $e->errorCode === 'locked' && $e->details['username'] === 'Редактор');
$e = throws('drafts: the same asked on the draft', ApiException::class, function () use ($dInvoke, $dDev, $dDraft) { $dInvoke($dDev, 'apply_draft', $dDraft, array('confirm' => true)); });
check('drafts: the lock of the original counts whichever resource the call was made on', $e && $e->errorCode === 'locked' && $dSite->row('modResource', $dDraft) !== null);
$dPlanOpen = $dInvoke($dDev, 'apply_draft', $dDraft);
check('drafts: the plan shows the open page', $dPlanOpen['open_in_manager']['username'] === 'Редактор');
$dSecond = $dInvoke($dDev, 'create_draft', $dSection['id']);
check('drafts: a draft can be made of a page that is open (the page is not changed)', is_int($dSecond['draft_id']));
$dInvoke($dDev, 'discard_draft', $dSection['id'], array('confirm' => true));
$dSite->unlockResource($dA['id']);
$dSite->lockResource($dDraft, 602);
$e = throws('drafts: discarding a draft that is open is refused', ApiException::class, function () use ($dInvoke, $dDev, $dA) { $dInvoke($dDev, 'discard_draft', $dA['id'], array('confirm' => true)); });
check('drafts: discarding an open draft is locked', $e && $e->errorCode === 'locked' && $dSite->row('modResource', $dDraft) !== null);
$dSite->unlockResource($dDraft);

// a change of template through a draft
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dDraft, 'fields' => array('template' => 3)));
$dInvoke($dDev, 'apply_draft', $dDraft, array('confirm' => true), array('force' => true));
check('drafts: the template is copied and the TVs follow it', (int) $dSite->row('modResource', $dA['id'])['template'] === 3 && $dTv($dA['id'])[20] === 'Новый подзаголовок');

// the manager: DraftService
$dB = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Контакты', 'alias' => 'kontakty', 'template' => 2, 'content' => 'Адрес: старый', 'published' => true), 'relations' => array('tvs' => array('seo' => 'один'))));
$dBDraft = $dInvoke($dDev, 'create_draft', $dB['id'])['draft_id'];
$call($dDev, 'update', array('kind' => 'resource', 'id' => $dBDraft, 'fields' => array('content' => 'Адрес: новый')));
$dService = new DraftService($dSite, $dSite->user);
$dRows = $dService->drafts();
check('drafts: the manager service lists the drafts with edit links', count($dRows) === 1 && $dRows[0]['original_title'] === 'Контакты' && $dRows[0]['edit_url'] === '/manager/?a=resource/update&id=' . $dB['id']
    && $dRows[0]['edit_draft_url'] === '/manager/?a=resource/update&id=' . $dBDraft && $dRows[0]['author'] === 'Рабочий');
$dManagerPlan = $dService->apply($dB['id']);
check('drafts: the manager gets the plan first', $dManagerPlan['performed'] === false && strpos($dManagerPlan['changes']['content']['diff'], '+Адрес: новый') !== false && $dSite->row('modResource', $dBDraft) !== null);
$dManagerApply = $dService->apply($dB['id'], true);
$dManagerRow = $dLast();
check('drafts: a manager apply is journaled as the manager with the user', $dManagerApply['applied'] === true && $dSite->row('modResource', $dB['id'])['content'] === 'Адрес: новый' && $dSite->row('modResource', $dBDraft) === null
    && $dManagerRow['source'] === 'manager' && (int) $dManagerRow['user_id'] === 2 && $dManagerRow['token_id'] === null && $dManagerRow['summary'] === "apply draft {$dBDraft} to resource {$dB['id']}" && $dCount('drafts') === 0);
$dBDraft2 = $dInvoke($dDev, 'create_draft', $dB['id'])['draft_id'];
$dService->discard($dBDraft2, true);
check('drafts: a manager discard is journaled as the manager', $dSite->row('modResource', $dBDraft2) === null && $dLast()['source'] === 'manager' && $dCount('drafts') === 0);
$e = throws('drafts: the manager gets the API\'s refusals', ApiException::class, function () use ($dService, $dB) { $dService->apply($dB['id'], true); });
check('drafts: applying a page without a draft is validation_failed', $e && $e->errorCode === 'validation_failed');
check('drafts: no stale link or archive row of an open draft remains', $dCount('drafts') === 0 && $dCount('draft_archive', 'draft_id = ?', array($dBDraft)) === 1);

// Draft-only tokens share the normal resource draft and update paths, with narrower authorization.
$draftTokenService = new \ModxMCP\Manager\TokenService($dSite, $dSite->user);
$draftIssued = $draftTokenService->create(array('label' => 'Черновики для сайта', 'scope' => 'draft_only'));
$draftRecord = $dTokens->authenticate($draftIssued['token']);
check('draft-only: a manager can issue a token with a persistent draft-only scope', $draftRecord['scope'] === 'draft_only' && $draftRecord['id'] === $draftIssued['id']);
$draftEditor = $dActor($draftRecord);
$otherIssued = $dTokens->create('Second editor', 'draft_only');
$otherEditor = $dActor($dTokens->authenticate($otherIssued['token']));
$draftCapabilities = $call($draftEditor, 'capabilities');
check('draft-only: advertises just the permitted tools and resource kind', $draftCapabilities['kinds'] === array('resource')
    && $draftCapabilities['tools'] === array('modx_capabilities', 'modx_site_info', 'modx_describe', 'modx_help', 'modx_list', 'modx_get', 'modx_update', 'modx_invoke', 'modx_resource_tree', 'modx_check_page')
    && $draftCapabilities['tools'] === array_column(Manifest::tools($draftEditor), 'name') && Manifest::prompts($draftEditor) === array());
$draftDescription = $call($draftEditor, 'describe', array('kind' => 'resource'));
check('draft-only: describes only available operations and marks non-editorial fields read-only', array_column($draftDescription['operations'], 'op') === array('create_draft', 'stage_product_prices', 'list_drafts')
    && array_column(array_filter($draftDescription['fields'], function ($field) { return empty($field['read_only']); }), 'name')
        === array('pagetitle', 'longtitle', 'description', 'introtext', 'menutitle', 'content')
    && !in_array(true, array_column($draftDescription['relations'], 'writable'), true));

$draftOriginal = $dGet($dB['id']);
$draftUnpublished = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Unpublished page', 'published' => false)));
$ownDraft = $dInvoke($draftEditor, 'create_draft', $dB['id'])['draft_id'];
$otherDraft = $dInvoke($otherEditor, 'create_draft', $dSection['id'])['draft_id'];
check('draft-only: each token lists only the draft it created', array_column($dInvoke($draftEditor, 'list_drafts', null)['drafts'], 'draft_id') === array($ownDraft)
    && array_column($dInvoke($otherEditor, 'list_drafts', null)['drafts'], 'draft_id') === array($otherDraft)
    && count($dService->drafts()) === 2);
$draftEdit = array('kind' => 'resource', 'id' => $ownDraft, 'fields' => array('content' => "Новый адрес\nУлица Мира"));
$draftRevision = $dGet($ownDraft)['revision'];
$draftPlan = $call($dActor(array('plan_only' => true) + $draftRecord), 'update', $draftEdit + array('expected_revision' => $draftRevision));
check('draft-only: plan-only previews an allowed edit without saving', !empty($draftPlan['planned']) && $dGet($ownDraft)['revision'] === $draftRevision);
$call($draftEditor, 'update', $draftEdit + array('expected_revision' => $draftRevision));
$savedDraft = $dGet($ownDraft);
check('draft-only: saves text on its own draft without changing the original', $savedDraft['fields']['content'] === "Новый адрес\nУлица Мира"
    && !$savedDraft['fields']['published'] && $dGet($dB['id'])['revision'] === $draftOriginal['revision']);

foreach (array(
    array('update', array('id' => $dB['id']) + $draftEdit, 'forbidden_scope'),
    array('update', array('id' => $draftUnpublished['id'], 'dry_run' => true) + $draftEdit, 'forbidden_scope'),
    array('update', array('id' => $otherDraft) + $draftEdit, 'forbidden_scope'),
    array('update', array('fields' => array('published' => true)) + $draftEdit, 'forbidden_scope'),
    array('update', array('fields' => array('pub_date' => '2030-11-08')) + $draftEdit, 'forbidden_scope'),
    array('update', array('fields' => array('content' => '<p>Markup</p>')) + $draftEdit, 'validation_failed'),
    array('update', array('relations' => array('tvs' => array('seo' => 'new'))) + $draftEdit, 'forbidden_scope'),
    array('update', array('force' => true) + $draftEdit, 'forbidden_scope'),
    array('update', array('skip_lint' => true) + $draftEdit, 'forbidden_scope'),
    array('update', array('expected_revision' => $draftRevision) + $draftEdit, 'revision_conflict'),
    array('invoke', array('kind' => 'resource', 'id' => $ownDraft, 'op' => 'apply_draft', 'args' => array('confirm' => true), 'force' => true), 'forbidden_scope'),
    array('invoke', array('kind' => 'resource', 'id' => $ownDraft, 'op' => 'discard_draft', 'dry_run' => true), 'forbidden_scope'),
    array('create', array('kind' => 'resource'), 'unavailable'),
    array('bulk_resources', array(), 'unavailable'),
    array('undo', array(), 'unavailable'),
    array('get', array('kind' => 'template', 'id' => 2), 'unavailable'),
) as $case => list($draftAction, $draftArgs, $draftCode)) {
    $e = throws('draft-only: refuses unauthorized request ' . $case, ApiException::class, function () use ($call, $draftEditor, $draftAction, $draftArgs) {
        $call($draftEditor, $draftAction, $draftArgs);
    });
    check('draft-only: expected refusal code for request ' . $case, $e && $e->errorCode === $draftCode);
}
check('draft-only: refusals leave both original and draft unchanged', $dGet($ownDraft)['revision'] === $savedDraft['revision']
    && $dGet($dB['id'])['revision'] === $draftOriginal['revision']);
$draftRaw = $dSite->row('modResource', $ownDraft);
foreach (array('published', 'deleted', 'pub_date', 'unpub_date') as $unsafeFlag) {
    $dSite->store('modResource', array($unsafeFlag => 1) + $draftRaw);
    $e = throws('draft-only: refuses unsafe draft ' . $unsafeFlag, ApiException::class, function () use ($call, $draftEditor, $draftEdit) {
        $call($draftEditor, 'update', $draftEdit + array('dry_run' => true));
    });
    check('draft-only: unsafe draft is outside its write scope', $e && $e->errorCode === 'forbidden_scope');
    $dSite->store('modResource', $draftRaw);
}
$dService->apply($ownDraft, true);
check('draft-only: manager approval applies the draft and removes it from the owner list', $dGet($dB['id'])['fields']['content'] === "Новый адрес\nУлица Мира"
    && $dLast()['source'] === 'manager' && $dInvoke($draftEditor, 'list_drafts', null)['drafts'] === array());

// Shareable previews use separate, short-lived credentials and expose just the changed plain text.
$preview = new \ModxMCP\Draft\DraftPreview($dSite);
$previewKeyPath = $dSite->getOption('core_path') . 'modxmcp-data/draft-preview/key.php';
$previewTime = (new DateTimeImmutable('2026-11-22T12:00:00+00:00'))->getTimestamp();
$previewSource = $call($dDev, 'create', array('kind' => 'resource', 'fields' => array('pagetitle' => 'Page to review',
    'description' => 'Description to clear', 'content' => '<p>Original body</p>', 'introtext' => 'Unchanged introduction')));
$previewId = $dInvoke($dDev, 'create_draft', $previewSource['id'])['draft_id'];
$previewLink = function () use ($dSite, $previewId) { return (new DraftStore($dSite))->ofDraft($previewId); };
$previewUpdate = function (array $fields) use ($call, $dDev, $previewId) {
    $call($dDev, 'update', array('kind' => 'resource', 'id' => $previewId, 'fields' => $fields));
};
$previewUnavailable = function ($label) use ($preview, $previewId, $previewTime) {
    $e = throws($label, ApiException::class, function () use ($preview, $previewId, $previewTime) {
        $preview->issue($previewId, $previewTime);
    });
    check($label . ' reports preview unavailable', $e && $e->errorCode === 'preview_unavailable');
};
$unsigned = 'v1.1.' . $previewId . '.' . ($previewTime + 100) . '.' . str_repeat('0', 64) . '.' . str_repeat('0', 64);
check('draft preview: redemption never provisions a signing key', $preview->redeem($unsigned, $previewTime) === null && !is_file($previewKeyPath));
$previewUnavailable('draft preview: refuses issuance before any change');
$previewUpdate(array('content' => '<p>Edited markup body</p>'));
$previewUnavailable('draft preview: refuses issuance for markup-only changes');
check('draft preview: a failed issuance does not provision a key', !is_file($previewKeyPath));
$previewUpdate(array('pagetitle' => 'Новый заголовок', 'description' => ''));
$testTimezone = date_default_timezone_get();
date_default_timezone_set('Asia/Irkutsk');
try { $previewToken = $preview->issue($previewId, $previewTime); } finally { date_default_timezone_set($testTimezone); }
$previewParts = explode('.', $previewToken);
$previewFields = array('pagetitle' => 'Новый заголовок', 'description' => '');
check('draft preview: signature is bound to the draft row and expires after 30 UTC minutes', $previewParts[0] === 'v1'
    && (int) $previewParts[1] === $previewLink()['id'] && (int) $previewParts[2] === $previewId && (int) $previewParts[3] === $previewTime + 1800);
$previewStoredKey = file_get_contents($previewKeyPath);
$previewGuard = \ModxMCP\Request\RequestStore::FILE_GUARD;
check('draft preview: signing key is guarded, random-sized and restricted', substr($previewStoredKey, 0, strlen($previewGuard)) === $previewGuard
    && preg_match('/^[a-f0-9]{64}$/D', substr($previewStoredKey, strlen($previewGuard))) === 1
    && (DIRECTORY_SEPARATOR === '\\' || (fileperms($previewKeyPath) & 0777) === 0600));
check('draft preview: excludes unchanged values and changed markup while retaining an empty change',
    $preview->redeem($previewToken, $previewTime + 1799) === $previewFields);
$modifiedSignature = substr($previewToken, 0, -1) . (substr($previewToken, -1) === 'a' ? 'b' : 'a');
check('draft preview: rejects an invalid HMAC, an expired grant and a grant from the future', $preview->redeem($modifiedSignature, $previewTime) === null
    && $preview->redeem($previewToken, $previewTime + 1800) === null && $preview->redeem($previewToken, $previewTime - 1) === null);

$previewHTTPS = array('HTTPS' => 'on', 'REMOTE_ADDR' => '192.0.2.20');
$previewHttp = array('REMOTE_ADDR' => '192.0.2.20', 'HTTP_X_FORWARDED_PROTO' => 'https');
$previewEndpoint = 'https://example.test/assets/components/modxmcp/draft-preview.php';
$dSite->options['assets_url'] = '/assets/';
check('draft preview: a configured HTTPS site issues a fragment link', strpos($dService->share($previewId, $previewHTTPS)['url'], $previewEndpoint . '#v1.') === 0);
check('draft preview: untrusted forwarding and plain HTTP cannot issue a preview', DraftService::shareEndpoint($dSite, $previewHttp) === null
    && !\ModxMCP\Draft\DraftPreview::isHttps($dSite, $previewHttp));
$dSite->options['modxmcp.trusted_proxies'] = '192.0.2.20';
check('draft preview: trusts configured HTTPS proxy detection', DraftService::shareEndpoint($dSite, $previewHttp) === $previewEndpoint
    && DraftService::shareEndpoint($dSite, $previewHTTPS) === null);
unset($dSite->options['modxmcp.trusted_proxies']);
$dSite->options['modxmcp.assets_url'] = 'https://elsewhere.example/assets/components/modxmcp/';
check('draft preview: rejects a configured preview URL on another origin', DraftService::shareEndpoint($dSite, $previewHTTPS) === null);
$dSite->options['modxmcp.assets_url'] = 'https://example.test:443/assets/components/modxmcp/';
check('draft preview: normalizes the default HTTPS port for origin comparison', DraftService::shareEndpoint($dSite, $previewHTTPS)
    === 'https://example.test:443/assets/components/modxmcp/draft-preview.php');
unset($dSite->options['modxmcp.assets_url']);
$dSite->options['modxmcp.enabled'] = false;
check('draft preview: the component kill switch prevents issuance', DraftService::shareEndpoint($dSite, $previewHTTPS) === null);
unset($dSite->options['modxmcp.enabled']);

require_once $dCore . 'processors/mgr/drafts/share.class.php';
$previewManager = new ModxmcpDraftsShareProcessor($dSite, array('id' => $previewId));
$savedPreviewUser = $dSite->user;
$dSite->user = null;
check('draft preview: processor requires a current manager session', !$previewManager->checkPermissions());
$dSite->user = new class {
    public function hasSessionContext($key) { return $key === 'mgr'; }
};
$dSite->options['fake_permissions'] = array('settings' => false);
check('draft preview: a manager session without settings cannot issue links', !$previewManager->checkPermissions());
$dSite->options['fake_permissions'] = array('settings' => true);
check('draft preview: a manager with settings may issue links', $previewManager->checkPermissions());
unset($dSite->options['fake_permissions']);
$dSite->user = $savedPreviewUser;
$savedPreviewMethod = $_SERVER['REQUEST_METHOD'] ?? null;
$_SERVER['REQUEST_METHOD'] = 'GET';
check('draft preview: processor rejects GET without issuing a link', !$previewManager->process()['success']);
if ($savedPreviewMethod === null) { unset($_SERVER['REQUEST_METHOD']); } else { $_SERVER['REQUEST_METHOD'] = $savedPreviewMethod; }

$initialDraft = $dSite->row('modResource', $previewId);
foreach (array('published', 'deleted', 'pub_date', 'unpub_date') as $flag) {
    $dSite->store('modResource', array($flag => 1) + $initialDraft);
    $previewUnavailable('draft preview: unsafe draft flag ' . $flag);
    check('draft preview: cannot redeem when ' . $flag . ' changes', $preview->redeem($previewToken, $previewTime) === null);
    $dSite->store('modResource', $initialDraft);
}
$previewUpdate(array('content' => '<p>Further markup edit</p>'));
check('draft preview: even a change to an unshared editable field invalidates the link', $preview->redeem($previewToken, $previewTime) === null);
$beforeDiscardToken = $preview->issue($previewId, $previewTime);
$beforeDiscardLink = $previewLink()['id'];
$dService->discard($previewId, true);
check('draft preview: removal invalidates the link', $preview->redeem($beforeDiscardToken, $previewTime) === null);
$call($dDev, 'undo', array('changeset_id' => $dLast()['id'], 'confirm' => true));
check('draft preview: undo restores the draft without reviving its old share', $previewLink()['id'] !== $beforeDiscardLink
    && $preview->redeem($beforeDiscardToken, $previewTime) === null && $preview->redeem($preview->issue($previewId, $previewTime), $previewTime) === $previewFields);
$dSite->pdo->prepare('UPDATE modx_modxmcp_drafts SET base_state = NULL WHERE draft_id = ?')->execute(array($previewId));
$previewUnavailable('draft preview: a draft without a saved base snapshot cannot issue a link');

// Product drafts use the same draft links and manager approval with independent staged prices.
$pdOwner = $sActor('draft_only', array('id' => 701));
$pdOther = $sActor('draft_only', array('id' => 702));
$pdTemplate = 9101;
$sSite->store('modTemplate', array('id' => $pdTemplate, 'templatename' => 'Product template'));
$sSite->store('modTemplateVar', array('id' => 9101, 'name' => 'pd_label', 'default_text' => '', 'caption' => '', 'type' => 'text', 'category' => 0));
$sSite->store('modTemplateVarTemplate', array('tmplvarid' => 9101, 'templateid' => $pdTemplate, 'rank' => 0));
$sSite->store('modUser', array('id' => 82, 'username' => 'Manager', 'primary_group' => 0));
$pdProduct = $call($sEditor, 'create', array('kind' => 'resource', 'fields' => array('class_key' => 'msProduct',
    'parent' => $catPhones, 'pagetitle' => 'Черновик товара', 'content' => 'Original text', 'description' => 'Original description',
    'template' => $pdTemplate, 'published' => true), 'relations' => array('tvs' => array('pd_label' => 'Original TV'),
    'ms2_data' => array('price' => 300, 'old_price' => 600, 'article' => 'DRAFT-45',
    'tags' => array('existing')), 'ms2_categories' => array($catAccessories))));
$pdOriginalId = $pdProduct['id'];
$pdRead = function ($id) use ($call, $sAdmin) { return $call($sAdmin, 'get', array('kind' => 'resource', 'id' => $id)); };
$pdOriginal = $pdRead($pdOriginalId);
$pdTablesBefore = $sTables();
$pdCreate = $dInvoke($pdOwner, 'create_draft', $pdOriginalId);
$pdId = $pdCreate['draft_id'];
$pdShadow = $sSite->row('modResource', $pdId);
check('product draft: an unpublished hidden modDocument with the original context and parent', $pdCreate['product_draft'] && $pdCreate['preview_url'] === ''
    && $pdShadow['class_key'] === 'modDocument' && (int) $pdShadow['template'] === 0 && (int) $pdShadow['parent'] === $catPhones
    && $pdShadow['context_key'] === $sSite->row('modResource', $pdOriginalId)['context_key'] && !$pdShadow['published'] && $pdShadow['hidemenu']
    && !$pdShadow['searchable'] && !(int) $pdShadow['pub_date'] && !(int) $pdShadow['unpub_date']);
check('product draft: creating a shadow keeps the original revision and adds no miniShop2 rows', $pdRead($pdOriginalId)['revision'] === $pdOriginal['revision']
    && $sTables() === $pdTablesBefore && !$sSite->getCount('modTemplateVarResource', array('contentid' => $pdId)));
$sSite->store('modResource', array('properties' => '{"custom":{"keep":"yes"}}') + $pdShadow);
$pdStageOp = 'stage_product_prices';
$pdStagePlan = $dInvoke($sActor('draft_only', array('id' => 701, 'plan_only' => true)), $pdStageOp, $pdId, array('price' => 123.45));
check('product draft: plan-only stages nothing and returns its price proposal', $pdStagePlan['planned'] && $pdStagePlan['staged_prices'] === array('price' => 123.45)
    && (array) $pdRead($pdId)['staged_prices'] === array());
$pdStaged = $dInvoke($pdOwner, $pdStageOp, $pdId, array('price' => 375));
$pdStagedRead = $pdRead($pdId);
check('product draft: explicitly staged prices and shadow revision are returned by stage, get and list', $pdStaged['staged_prices'] === array('price' => 375.0)
    && $pdStagedRead['staged_prices'] === $pdStaged['staged_prices'] && $pdStagedRead['revision'] === $pdStaged['revision']
    && $call($pdOwner, 'list', array('kind' => 'resource', 'where' => array('id' => $pdId)))['items'][0]['staged_prices'] === $pdStaged['staged_prices']);
$call($pdOwner, 'update', array('kind' => 'resource', 'id' => $pdId, 'fields' => array('content' => 'Новый текст')));
$pdProperties = $sSite->getObject('modResource', $pdId)->get('properties');
check('product draft: normal text edit preserves staged and unrelated native properties', $pdRead($pdId)['staged_prices'] === array('price' => 375.0)
    && $pdProperties['custom'] === array('keep' => 'yes') && $pdRead($pdOriginalId)['revision'] === $pdOriginal['revision']);
$pdSaved = $pdRead($pdId);
$sSite->lockResource($pdId, 82);
$e = throws('product draft: an open manager draft prevents staging', ApiException::class, function () use ($dInvoke, $pdOwner, $pdStageOp, $pdId) {
    $dInvoke($pdOwner, $pdStageOp, $pdId, array('price' => 1));
});
check('product draft: manager lock returns locked', $e && $e->errorCode === 'locked');
$e = throws('product draft: a draft-only token cannot force staging past the manager lock', ApiException::class, function () use ($dInvoke, $pdOwner, $pdStageOp, $pdId) {
    $dInvoke($pdOwner, $pdStageOp, $pdId, array('price' => 1), array('force' => true));
});
check('product draft: force by a restricted token is forbidden', $e && $e->errorCode === 'forbidden_scope');
$sSite->unlockResource($pdId);
foreach (array(
    array($pdOwner, $pdStageOp, $pdOriginalId, array('price' => 1), 'forbidden_scope'),
    array($pdOther, $pdStageOp, $pdId, array('price' => 1), 'forbidden_scope'),
    array($pdOwner, $pdStageOp, $pdId, array('price' => -1), 'validation_failed'),
    array($pdOwner, $pdStageOp, $pdId, array('price' => 1.001), 'validation_failed'),
    array($pdOwner, $pdStageOp, $pdId, array('price' => 10000000000), 'validation_failed'),
    array($pdOwner, $pdStageOp, $pdId, array('old_price' => '2'), 'validation_failed'),
    array($pdOwner, $pdStageOp, $pdId, array(), 'validation_failed'),
    array($sActor('content', array('denied_groups' => array('minishop2'))), $pdStageOp, $pdId, array('price' => 2), 'unavailable'),
    array($pdOwner, 'apply_draft', $pdId, array('confirm' => true), 'forbidden_scope'),
    array($pdOwner, 'discard_draft', $pdId, array('confirm' => true), 'forbidden_scope'),
) as $index => list($pdActor, $pdOp, $pdTarget, $pdArgs, $pdCode)) {
    $e = throws('product draft: invalid stage or write request ' . $index, ApiException::class, function () use ($dInvoke, $pdActor, $pdOp, $pdTarget, $pdArgs) {
        $dInvoke($pdActor, $pdOp, $pdTarget, $pdArgs);
    });
    check('product draft: expected rejection ' . $index, $e && $e->errorCode === $pdCode);
}
foreach (array(array('published' => true), array('pub_date' => '2030-11-08'), array('class_key' => 'msProduct')) as $pdFields) {
    throws('product draft: rejects publishing, scheduling or conversion through update', ApiException::class, function () use ($call, $sEditor, $pdId, $pdFields) {
        $call($sEditor, 'update', array('kind' => 'resource', 'id' => $pdId, 'fields' => $pdFields));
    });
}
foreach (array(false, true) as $pdDry) {
    throws('product draft: bulk publish refuses the shadow even when forced', ApiException::class, function () use ($call, $sEditor, $pdId, $pdDry) {
        $call($sEditor, 'bulk_resources', array('operation' => 'publish', 'ids' => array($pdId), 'dry_run' => $pdDry, 'force' => true));
    });
}
check('product draft: all denied requests left the shadow and live item unchanged', $pdRead($pdId)['revision'] === $pdSaved['revision']
    && $pdRead($pdOriginalId)['revision'] === $pdOriginal['revision']);

$pdService = new DraftService($sSite, $sSite->getObject('modUser', 82));
$pdPlan = $pdService->apply($pdId);
check('product draft: manager review shows only the staged price and changed text', $pdPlan['prices'] === array('price' => array('old' => 300.0, 'new' => 375.0))
    && array_keys($pdPlan['changes']) === array('content') && (array) $pdPlan['tvs'] === array());
$call($sEditor, 'update', array('kind' => 'resource', 'id' => $pdOriginalId, 'fields' => array('description' => 'Other edit'),
    'relations' => array('ms2_data' => array('old_price' => 850))));
$pdBeforeApply = $pdRead($pdOriginalId);
$e = throws('product draft: the full product revision still detects conflicts', ApiException::class, function () use ($pdService, $pdId) { $pdService->apply($pdId, true); });
check('product draft: external text or product data changes require force', $e && $e->errorCode === 'revision_conflict');
$sSite->options['modxmcp.disabled_groups'] = 'minishop2';
$e = throws('product draft: force cannot apply with the integration disabled', ApiException::class, function () use ($dInvoke, $sActor, $pdId) {
    $dInvoke($sActor('admin'), 'apply_draft', $pdId, array('confirm' => true), array('force' => true));
});
check('product draft: disabled group is the reason for refusal', $e && $e->errorCode === 'unavailable' && $e->details['reason'] === 'disabled_group');
unset($sSite->options['modxmcp.disabled_groups']);
$pdApplied = $pdService->apply($pdId, true, true);
$pdAfterApply = $pdRead($pdOriginalId);
$pdExpectedData = array_replace((array) $pdBeforeApply['relations']['ms2_data'], array('price' => 375.0));
check('product draft: forced apply preserves unstaged price, product data, other text and relations', $pdApplied['applied_prices'] === array('price')
    && $pdAfterApply['fields']['description'] === 'Other edit' && $pdAfterApply['fields']['content'] === 'Новый текст'
    && $pdAfterApply['fields']['class_key'] === 'msProduct' && $pdAfterApply['fields']['published'] && $pdAfterApply['fields']['template'] === $pdTemplate
    && $pdAfterApply['relations']['tvs'] === array('pd_label' => 'Original TV') && $pdAfterApply['relations']['ms2_data'] === $pdExpectedData
    && $pdAfterApply['relations']['ms2_categories'] === $pdBeforeApply['relations']['ms2_categories'] && $sSite->row('modResource', $pdId) === null);
$call($sAdmin, 'undo', array('changeset_id' => $pdApplied['changeset_id'], 'confirm' => true));
check('product draft: undo restores original revision, link and staged shadow prices', $pdRead($pdOriginalId)['revision'] === $pdBeforeApply['revision']
    && $pdRead($pdId)['staged_prices'] === array('price' => 375.0) && $pdRead($pdId)['draft_of'] === $pdOriginalId
    && $sSite->getObject('modResource', $pdId)->get('properties')['custom'] === array('keep' => 'yes'));
$pdService->discard($pdId, true);
check('product draft: discard leaves the live product unchanged', $pdRead($pdOriginalId)['revision'] === $pdBeforeApply['revision']
    && $sSite->row('modResource', $pdId) === null);

$pdPriceOnly = $dInvoke($pdOwner, 'create_draft', $pdOriginalId)['draft_id'];
$dInvoke($pdOwner, $pdStageOp, $pdPriceOnly, array('old_price' => 0));
$pdPriceApply = $pdService->apply($pdPriceOnly, true);
check('product draft: a price-only apply writes zero with no editorial changes', $pdPriceApply['applied_fields'] === array()
    && $pdPriceApply['applied_prices'] === array('old_price') && $pdRead($pdOriginalId)['relations']['ms2_data']['old_price'] === 0.0);
$call($sAdmin, 'undo', array('changeset_id' => $pdPriceApply['changeset_id'], 'confirm' => true));
check('product draft: price-only undo restores the previous price and staged zero', $pdRead($pdOriginalId)['relations']['ms2_data']['old_price'] === 850.0
    && $pdRead($pdPriceOnly)['staged_prices'] === array('old_price' => 0.0));
$pdSafeShadow = $sSite->row('modResource', $pdPriceOnly);
$sSite->store('modResource', array('published' => 1) + $pdSafeShadow);
$e = throws('product draft: forcing approval cannot use a published shadow', ApiException::class, function () use ($pdService, $pdPriceOnly) {
