$sSite->store('msProductLink', array('link' => 990, 'master' => $gId, 'slave' => $phoneId));
$sSite->store('msProductLink', array('link' => 991, 'master' => $phoneId, 'slave' => $gId));
$gLinks = $sSite->tableDump('msProductLink');
