$expectedMask = array_replace($secretSourceFields, array('accessKeyId' => '[hidden]', 'secretAccessKey' => '[hidden]'));
ksort($expectedMask, SORT_STRING);
foreach (array('read', 'content', 'develop') as $scope) {
