    && $swSite->getObject('modSystemSetting', array('key' => 'modxmcp.enabled'))->get('value') === '0'
    && $swSite->getOption('modxmcp.enabled') === '0' && $swApi->enabled() === false && $swSite->getCacheManager()->refreshes >= 1);
